INSERT INTO `acupoint_knowledge` (`code`, `point_number`, `name`, `pinyin`, `meridian_code`, `meridian_name`, `meridian_english`, `model_id`, `body_area`, `standard_location`, `child_location`, `child_description`, `safety_tip`, `source_name`, `source_link`, `position_x`, `position_y`, `position_z`, `sort_order`, `enabled`) VALUES ('LU-1', 1, '中府', 'Zhongfu', 'LU', '手太阴肺经', 'Lung Meridian', 'p1', '胸部', '在前胸部，横平第1肋间隙，锁骨下窝外侧，前正中线旁开6寸。注：先确定云门（LU2），中府即在云门下1寸。', '转动3D小铜人，看向上肢、胸部。在胸部找到“中府星”的发光点，点一下就完成观察。', '今天的星河门牌叫中府。它不是按钮，而是帮我们读懂手太阴肺经的文化标记。', '只看3D铜人和文化图卡，不做身体操作；有问题请告诉老师或家长。', 'GB/T 12346-2021《经穴名称与定位》', 'https://openstd.samr.gov.cn/bzgk/std/newGbInfo?hcno=397548AE7248D3D87DD15E0AB8107185', -13.267798006864483, 46.00000000000004, -1.0999999999999999, 1, 1) ON DUPLICATE KEY UPDATE `point_number`=VALUES(`point_number`), `name`=VALUES(`name`), `pinyin`=VALUES(`pinyin`), `meridian_code`=VALUES(`meridian_code`), `meridian_name`=VALUES(`meridian_name`), `meridian_english`=VALUES(`meridian_english`), `model_id`=VALUES(`model_id`), `body_area`=VALUES(`body_area`), `standard_location`=VALUES(`standard_location`), `child_location`=VALUES(`child_location`), `child_description`=VALUES(`child_description`), `safety_tip`=VALUES(`safety_tip`), `source_name`=VALUES(`source_name`), `source_link`=VALUES(`source_link`), `position_x`=VALUES(`position_x`), `position_y`=VALUES(`position_y`), `position_z`=VALUES(`position_z`), `sort_order`=VALUES(`sort_order`), `enabled`=VALUES(`enabled`);
INSERT INTO `acupoint_knowledge` (`code`, `point_number`, `name`, `pinyin`, `meridian_code`, `meridian_name`, `meridian_english`, `model_id`, `body_area`, `standard_location`, `child_location`, `child_description`, `safety_tip`, `source_name`, `source_link`, `position_x`, `position_y`, `position_z`, `sort_order`, `enabled`) VALUES ('LU-2', 2, '云门', 'Yunmen', 'LU', '手太阴肺经', 'Lung Meridian', 'p2', '肩臂部', '在前胸部，锁骨下窝凹陷中，肩胛骨喙突内缘，前正中线旁开6寸。', '转动3D小铜人，看向上臂、肩部。在肩臂部找到“云门星”的发光点，点一下就完成观察。', '云门的档案有两个关键词：肩臂部和手太阴肺经。把它们连起来，线索就完整了。', '只看3D铜人和文化图卡，不做身体操作；有问题请告诉老师或家长。', 'GB/T 12346-2021《经穴名称与定位》', 'https://openstd.samr.gov.cn/bzgk/std/newGbInfo?hcno=397548AE7248D3D87DD15E0AB8107185', -11.26779800686449, 48.60000000000008, -3.4000000000000026, 2, 1) ON DUPLICATE KEY UPDATE `point_number`=VALUES(`point_number`), `name`=VALUES(`name`), `pinyin`=VALUES(`pinyin`), `meridian_code`=VALUES(`meridian_code`), `meridian_name`=VALUES(`meridian_name`), `meridian_english`=VALUES(`meridian_english`), `model_id`=VALUES(`model_id`), `body_area`=VALUES(`body_area`), `standard_location`=VALUES(`standard_location`), `child_location`=VALUES(`child_location`), `child_description`=VALUES(`child_description`), `safety_tip`=VALUES(`safety_tip`), `source_name`=VALUES(`source_name`), `source_link`=VALUES(`source_link`), `position_x`=VALUES(`position_x`), `position_y`=VALUES(`position_y`), `position_z`=VALUES(`position_z`), `sort_order`=VALUES(`sort_order`), `enabled`=VALUES(`enabled`);
INSERT INTO `acupoint_knowledge` (`code`, `point_number`, `name`, `pinyin`, `meridian_code`, `meridian_name`, `meridian_english`, `model_id`, `body_area`, `standard_location`, `child_location`, `child_description`, `safety_tip`, `source_name`, `source_link`, `position_x`, `position_y`, `position_z`, `sort_order`, `enabled`) VALUES ('LU-3', 3, '天府', 'Tianfu', 'LU', '手太阴肺经', 'Lung Meridian', 'p3', '肩臂部', '在臂前外侧，腋前纹头下3寸，肱二头肌桡侧缘处。', '转动3D小铜人，看向上臂、肩部。在肩臂部找到“天府星”的发光点，点一下就完成观察。', '点亮天府后，肩臂部的地图多了一颗星。它是手太阴肺经路线的一站。', '只看3D铜人和文化图卡，不做身体操作；有问题请告诉老师或家长。', 'GB/T 12346-2021《经穴名称与定位》', 'https://openstd.samr.gov.cn/bzgk/std/newGbInfo?hcno=397548AE7248D3D87DD15E0AB8107185', -22.967798006864573, 32.39999999999985, -4.7, 3, 1) ON DUPLICATE KEY UPDATE `point_number`=VALUES(`point_number`), `name`=VALUES(`name`), `pinyin`=VALUES(`pinyin`), `meridian_code`=VALUES(`meridian_code`), `meridian_name`=VALUES(`meridian_name`), `meridian_english`=VALUES(`meridian_english`), `model_id`=VALUES(`model_id`), `body_area`=VALUES(`body_area`), `standard_location`=VALUES(`standard_location`), `child_location`=VALUES(`child_location`), `child_description`=VALUES(`child_description`), `safety_tip`=VALUES(`safety_tip`), `source_name`=VALUES(`source_name`), `source_link`=VALUES(`source_link`), `position_x`=VALUES(`position_x`), `position_y`=VALUES(`position_y`), `position_z`=VALUES(`position_z`), `sort_order`=VALUES(`sort_order`), `enabled`=VALUES(`enabled`);
INSERT INTO `acupoint_knowledge` (`code`, `point_number`, `name`, `pinyin`, `meridian_code`, `meridian_name`, `meridian_english`, `model_id`, `body_area`, `standard_location`, `child_location`, `child_description`, `safety_tip`, `source_name`, `source_link`, `position_x`, `position_y`, `position_z`, `sort_order`, `enabled`) VALUES ('LU-4', 4, '侠白', 'Xiabai', 'LU', '手太阴肺经', 'Lung Meridian', 'p4', '肩臂部', '在臂前外侧，腋前纹头下4寸，肱二头肌桡侧缘处。', '转动3D小铜人，看向上臂、肩部。在肩臂部找到“侠白星”的发光点，点一下就完成观察。', '在肩臂部的星点档案里，侠白和手太阴肺经站在同一条路线上。', '只看3D铜人和文化图卡，不做身体操作；有问题请告诉老师或家长。', 'GB/T 12346-2021《经穴名称与定位》', 'https://openstd.samr.gov.cn/bzgk/std/newGbInfo?hcno=397548AE7248D3D87DD15E0AB8107185', -23.56779800686458, 28.699999999999797, -4.999999999999999, 4, 1) ON DUPLICATE KEY UPDATE `point_number`=VALUES(`point_number`), `name`=VALUES(`name`), `pinyin`=VALUES(`pinyin`), `meridian_code`=VALUES(`meridian_code`), `meridian_name`=VALUES(`meridian_name`), `meridian_english`=VALUES(`meridian_english`), `model_id`=VALUES(`model_id`), `body_area`=VALUES(`body_area`), `standard_location`=VALUES(`standard_location`), `child_location`=VALUES(`child_location`), `child_description`=VALUES(`child_description`), `safety_tip`=VALUES(`safety_tip`), `source_name`=VALUES(`source_name`), `source_link`=VALUES(`source_link`), `position_x`=VALUES(`position_x`), `position_y`=VALUES(`position_y`), `position_z`=VALUES(`position_z`), `sort_order`=VALUES(`sort_order`), `enabled`=VALUES(`enabled`);
INSERT INTO `acupoint_knowledge` (`code`, `point_number`, `name`, `pinyin`, `meridian_code`, `meridian_name`, `meridian_english`, `model_id`, `body_area`, `standard_location`, `child_location`, `child_description`, `safety_tip`, `source_name`, `source_link`, `position_x`, `position_y`, `position_z`, `sort_order`, `enabled`) VALUES ('LU-5', 5, '尺泽', 'Chize', 'LU', '手太阴肺经', 'Lung Meridian', 'p5', '前臂与肘部', '在肘前侧，肘横纹上，肱二头肌腱桡侧缘凹陷中。注：屈肘，肘横纹上，曲池（LI11）与曲泽（PC3）之间。', '转动3D小铜人，看向上肢前臂、肘部。在前臂与肘部找到“尺泽星”的发光点，点一下就完成观察。', '尺泽对小侦探说：“请把我放进手太阴肺经档案。我的地图标签是前臂与肘部。”', '只看3D铜人和文化图卡，不做身体操作；有问题请告诉老师或家长。', 'GB/T 12346-2021《经穴名称与定位》', 'https://openstd.samr.gov.cn/bzgk/std/newGbInfo?hcno=397548AE7248D3D87DD15E0AB8107185', -24.16779800686459, 15.69999999999962, -4.6000000000000005, 5, 1) ON DUPLICATE KEY UPDATE `point_number`=VALUES(`point_number`), `name`=VALUES(`name`), `pinyin`=VALUES(`pinyin`), `meridian_code`=VALUES(`meridian_code`), `meridian_name`=VALUES(`meridian_name`), `meridian_english`=VALUES(`meridian_english`), `model_id`=VALUES(`model_id`), `body_area`=VALUES(`body_area`), `standard_location`=VALUES(`standard_location`), `child_location`=VALUES(`child_location`), `child_description`=VALUES(`child_description`), `safety_tip`=VALUES(`safety_tip`), `source_name`=VALUES(`source_name`), `source_link`=VALUES(`source_link`), `position_x`=VALUES(`position_x`), `position_y`=VALUES(`position_y`), `position_z`=VALUES(`position_z`), `sort_order`=VALUES(`sort_order`), `enabled`=VALUES(`enabled`);
INSERT INTO `acupoint_knowledge` (`code`, `point_number`, `name`, `pinyin`, `meridian_code`, `meridian_name`, `meridian_english`, `model_id`, `body_area`, `standard_location`, `child_location`, `child_description`, `safety_tip`, `source_name`, `source_link`, `position_x`, `position_y`, `position_z`, `sort_order`, `enabled`) VALUES ('LU-6', 6, '孔最', 'Kongzui', 'LU', '手太阴肺经', 'Lung Meridian', 'p6', '手腕部', '在前臂前外侧，腕掌侧远端横纹上7寸，尺泽（LU5）与太渊（LU9）连线上。', '转动3D小铜人，看向手部、腕部。在手腕部找到“孔最星”的发光点，点一下就完成观察。', '点亮孔最后，手腕部的地图多了一颗星。它是手太阴肺经路线的一站。', '只看3D铜人和文化图卡，不做身体操作；有问题请告诉老师或家长。', 'GB/T 12346-2021《经穴名称与定位》', 'https://openstd.samr.gov.cn/bzgk/std/newGbInfo?hcno=397548AE7248D3D87DD15E0AB8107185', -25.767798006864613, 7.499999999999648, -2.7000000000000015, 6, 1) ON DUPLICATE KEY UPDATE `point_number`=VALUES(`point_number`), `name`=VALUES(`name`), `pinyin`=VALUES(`pinyin`), `meridian_code`=VALUES(`meridian_code`), `meridian_name`=VALUES(`meridian_name`), `meridian_english`=VALUES(`meridian_english`), `model_id`=VALUES(`model_id`), `body_area`=VALUES(`body_area`), `standard_location`=VALUES(`standard_location`), `child_location`=VALUES(`child_location`), `child_description`=VALUES(`child_description`), `safety_tip`=VALUES(`safety_tip`), `source_name`=VALUES(`source_name`), `source_link`=VALUES(`source_link`), `position_x`=VALUES(`position_x`), `position_y`=VALUES(`position_y`), `position_z`=VALUES(`position_z`), `sort_order`=VALUES(`sort_order`), `enabled`=VALUES(`enabled`);
INSERT INTO `acupoint_knowledge` (`code`, `point_number`, `name`, `pinyin`, `meridian_code`, `meridian_name`, `meridian_english`, `model_id`, `body_area`, `standard_location`, `child_location`, `child_description`, `safety_tip`, `source_name`, `source_link`, `position_x`, `position_y`, `position_z`, `sort_order`, `enabled`) VALUES ('LU-7', 7, '列缺', 'Lieque', 'LU', '手太阴肺经', 'Lung Meridian', 'p7', '手腕部', '在前臂外侧，腕掌侧远端横纹上1.5寸，拇短伸肌腱与拇长展肌腱之间，拇长展肌腱沟的凹陷中。', '转动3D小铜人，看向手部、腕部。在手腕部找到“列缺星”的发光点，点一下就完成观察。', '点亮列缺后，手腕部的地图多了一颗星。它是手太阴肺经路线的一站。', '只看3D铜人和文化图卡，不做身体操作；有问题请告诉老师或家长。', 'GB/T 12346-2021《经穴名称与定位》', 'https://openstd.samr.gov.cn/bzgk/std/newGbInfo?hcno=397548AE7248D3D87DD15E0AB8107185', -26.96779800686463, -1.5000000000003426, -1.5000000000000004, 7, 1) ON DUPLICATE KEY UPDATE `point_number`=VALUES(`point_number`), `name`=VALUES(`name`), `pinyin`=VALUES(`pinyin`), `meridian_code`=VALUES(`meridian_code`), `meridian_name`=VALUES(`meridian_name`), `meridian_english`=VALUES(`meridian_english`), `model_id`=VALUES(`model_id`), `body_area`=VALUES(`body_area`), `standard_location`=VALUES(`standard_location`), `child_location`=VALUES(`child_location`), `child_description`=VALUES(`child_description`), `safety_tip`=VALUES(`safety_tip`), `source_name`=VALUES(`source_name`), `source_link`=VALUES(`source_link`), `position_x`=VALUES(`position_x`), `position_y`=VALUES(`position_y`), `position_z`=VALUES(`position_z`), `sort_order`=VALUES(`sort_order`), `enabled`=VALUES(`enabled`);
INSERT INTO `acupoint_knowledge` (`code`, `point_number`, `name`, `pinyin`, `meridian_code`, `meridian_name`, `meridian_english`, `model_id`, `body_area`, `standard_location`, `child_location`, `child_description`, `safety_tip`, `source_name`, `source_link`, `position_x`, `position_y`, `position_z`, `sort_order`, `enabled`) VALUES ('LU-8', 8, '经渠', 'Jingqu', 'LU', '手太阴肺经', 'Lung Meridian', 'p8', '手腕部', '在前臂前外侧，腕掌侧远端横纹上1寸，桡骨茎突与桡动脉之间。注：太渊上1寸。', '转动3D小铜人，看向手部、腕部。在手腕部找到“经渠星”的发光点，点一下就完成观察。', '经渠的档案有两个关键词：手腕部和手太阴肺经。把它们连起来，线索就完整了。', '只看3D铜人和文化图卡，不做身体操作；有问题请告诉老师或家长。', 'GB/T 12346-2021《经穴名称与定位》', 'https://openstd.samr.gov.cn/bzgk/std/newGbInfo?hcno=397548AE7248D3D87DD15E0AB8107185', -26.26779800686462, -3.500000000000344, -0.5000000000000001, 8, 1) ON DUPLICATE KEY UPDATE `point_number`=VALUES(`point_number`), `name`=VALUES(`name`), `pinyin`=VALUES(`pinyin`), `meridian_code`=VALUES(`meridian_code`), `meridian_name`=VALUES(`meridian_name`), `meridian_english`=VALUES(`meridian_english`), `model_id`=VALUES(`model_id`), `body_area`=VALUES(`body_area`), `standard_location`=VALUES(`standard_location`), `child_location`=VALUES(`child_location`), `child_description`=VALUES(`child_description`), `safety_tip`=VALUES(`safety_tip`), `source_name`=VALUES(`source_name`), `source_link`=VALUES(`source_link`), `position_x`=VALUES(`position_x`), `position_y`=VALUES(`position_y`), `position_z`=VALUES(`position_z`), `sort_order`=VALUES(`sort_order`), `enabled`=VALUES(`enabled`);
INSERT INTO `acupoint_knowledge` (`code`, `point_number`, `name`, `pinyin`, `meridian_code`, `meridian_name`, `meridian_english`, `model_id`, `body_area`, `standard_location`, `child_location`, `child_description`, `safety_tip`, `source_name`, `source_link`, `position_x`, `position_y`, `position_z`, `sort_order`, `enabled`) VALUES ('LU-9', 9, '太渊', 'Taiyuan', 'LU', '手太阴肺经', 'Lung Meridian', 'p9', '手腕部', '在腕前外侧，桡骨茎突与腕舟状骨之间，拇长展肌腱尺侧凹陷中。注：腕掌侧远端横纹桡侧，桡动脉搏动处。', '转动3D小铜人，看向手部、腕部。在手腕部找到“太渊星”的发光点，点一下就完成观察。', '太渊是手太阴肺经的经络小旗。它告诉我们：这条文化路线会经过手腕部。', '只看3D铜人和文化图卡，不做身体操作；有问题请告诉老师或家长。', 'GB/T 12346-2021《经穴名称与定位》', 'https://openstd.samr.gov.cn/bzgk/std/newGbInfo?hcno=397548AE7248D3D87DD15E0AB8107185', -27.367798006864636, -5.500000000000339, -0.30000000000000016, 9, 1) ON DUPLICATE KEY UPDATE `point_number`=VALUES(`point_number`), `name`=VALUES(`name`), `pinyin`=VALUES(`pinyin`), `meridian_code`=VALUES(`meridian_code`), `meridian_name`=VALUES(`meridian_name`), `meridian_english`=VALUES(`meridian_english`), `model_id`=VALUES(`model_id`), `body_area`=VALUES(`body_area`), `standard_location`=VALUES(`standard_location`), `child_location`=VALUES(`child_location`), `child_description`=VALUES(`child_description`), `safety_tip`=VALUES(`safety_tip`), `source_name`=VALUES(`source_name`), `source_link`=VALUES(`source_link`), `position_x`=VALUES(`position_x`), `position_y`=VALUES(`position_y`), `position_z`=VALUES(`position_z`), `sort_order`=VALUES(`sort_order`), `enabled`=VALUES(`enabled`);
INSERT INTO `acupoint_knowledge` (`code`, `point_number`, `name`, `pinyin`, `meridian_code`, `meridian_name`, `meridian_english`, `model_id`, `body_area`, `standard_location`, `child_location`, `child_description`, `safety_tip`, `source_name`, `source_link`, `position_x`, `position_y`, `position_z`, `sort_order`, `enabled`) VALUES ('LU-10', 10, '鱼际', 'Yuji', 'LU', '手太阴肺经', 'Lung Meridian', 'p10', '手腕部', '在手掌，第1掌骨桡侧中点赤白肉际处。', '转动3D小铜人，看向手部、腕部。在手腕部找到“鱼际星”的发光点，点一下就完成观察。', '鱼际对小侦探说：“请把我放进手太阴肺经档案。我的地图标签是手腕部。”', '只看3D铜人和文化图卡，不做身体操作；有问题请告诉老师或家长。', 'GB/T 12346-2021《经穴名称与定位》', 'https://openstd.samr.gov.cn/bzgk/std/newGbInfo?hcno=397548AE7248D3D87DD15E0AB8107185', -27.66779800686464, -7.7000000000003315, 2.1000000000000005, 10, 1) ON DUPLICATE KEY UPDATE `point_number`=VALUES(`point_number`), `name`=VALUES(`name`), `pinyin`=VALUES(`pinyin`), `meridian_code`=VALUES(`meridian_code`), `meridian_name`=VALUES(`meridian_name`), `meridian_english`=VALUES(`meridian_english`), `model_id`=VALUES(`model_id`), `body_area`=VALUES(`body_area`), `standard_location`=VALUES(`standard_location`), `child_location`=VALUES(`child_location`), `child_description`=VALUES(`child_description`), `safety_tip`=VALUES(`safety_tip`), `source_name`=VALUES(`source_name`), `source_link`=VALUES(`source_link`), `position_x`=VALUES(`position_x`), `position_y`=VALUES(`position_y`), `position_z`=VALUES(`position_z`), `sort_order`=VALUES(`sort_order`), `enabled`=VALUES(`enabled`);
INSERT INTO `acupoint_knowledge` (`code`, `point_number`, `name`, `pinyin`, `meridian_code`, `meridian_name`, `meridian_english`, `model_id`, `body_area`, `standard_location`, `child_location`, `child_description`, `safety_tip`, `source_name`, `source_link`, `position_x`, `position_y`, `position_z`, `sort_order`, `enabled`) VALUES ('LU-11', 11, '少商', 'Shaoshang', 'LU', '手太阴肺经', 'Lung Meridian', 'p11', '手腕部', '在手指，拇指末节桡侧，指甲根角侧上方0.1寸。', '转动3D小铜人，看向手部、腕部。在手腕部找到“少商星”的发光点，点一下就完成观察。', '少商带着一张“手太阴肺经”路线卡。把它收进档案，再认一认手腕部。', '只看3D铜人和文化图卡，不做身体操作；有问题请告诉老师或家长。', 'GB/T 12346-2021《经穴名称与定位》', 'https://openstd.samr.gov.cn/bzgk/std/newGbInfo?hcno=397548AE7248D3D87DD15E0AB8107185', -30.56779800686468, -13.200000000000312, 5.999999999999995, 11, 1) ON DUPLICATE KEY UPDATE `point_number`=VALUES(`point_number`), `name`=VALUES(`name`), `pinyin`=VALUES(`pinyin`), `meridian_code`=VALUES(`meridian_code`), `meridian_name`=VALUES(`meridian_name`), `meridian_english`=VALUES(`meridian_english`), `model_id`=VALUES(`model_id`), `body_area`=VALUES(`body_area`), `standard_location`=VALUES(`standard_location`), `child_location`=VALUES(`child_location`), `child_description`=VALUES(`child_description`), `safety_tip`=VALUES(`safety_tip`), `source_name`=VALUES(`source_name`), `source_link`=VALUES(`source_link`), `position_x`=VALUES(`position_x`), `position_y`=VALUES(`position_y`), `position_z`=VALUES(`position_z`), `sort_order`=VALUES(`sort_order`), `enabled`=VALUES(`enabled`);
INSERT INTO `acupoint_knowledge` (`code`, `point_number`, `name`, `pinyin`, `meridian_code`, `meridian_name`, `meridian_english`, `model_id`, `body_area`, `standard_location`, `child_location`, `child_description`, `safety_tip`, `source_name`, `source_link`, `position_x`, `position_y`, `position_z`, `sort_order`, `enabled`) VALUES ('LI-1', 1, '商阳', 'Shangyang', 'LI', '手阳明大肠经', 'Large Intestine Meridian', 'ig1', '手腕部', '在手指，食指末节桡侧，指甲根角侧上方0.1寸。', '转动3D小铜人，看向手部、腕部。在手腕部找到“商阳星”的发光点，点一下就完成观察。', '商阳的档案有两个关键词：手腕部和手阳明大肠经。把它们连起来，线索就完整了。', '只看3D铜人和文化图卡，不做身体操作；有问题请告诉老师或家长。', 'GB/T 12346-2021《经穴名称与定位》', 'https://openstd.samr.gov.cn/bzgk/std/newGbInfo?hcno=397548AE7248D3D87DD15E0AB8107185', 29.232201993135632, -20.00000000000036, 6.199999999999994, 12, 1) ON DUPLICATE KEY UPDATE `point_number`=VALUES(`point_number`), `name`=VALUES(`name`), `pinyin`=VALUES(`pinyin`), `meridian_code`=VALUES(`meridian_code`), `meridian_name`=VALUES(`meridian_name`), `meridian_english`=VALUES(`meridian_english`), `model_id`=VALUES(`model_id`), `body_area`=VALUES(`body_area`), `standard_location`=VALUES(`standard_location`), `child_location`=VALUES(`child_location`), `child_description`=VALUES(`child_description`), `safety_tip`=VALUES(`safety_tip`), `source_name`=VALUES(`source_name`), `source_link`=VALUES(`source_link`), `position_x`=VALUES(`position_x`), `position_y`=VALUES(`position_y`), `position_z`=VALUES(`position_z`), `sort_order`=VALUES(`sort_order`), `enabled`=VALUES(`enabled`);
INSERT INTO `acupoint_knowledge` (`code`, `point_number`, `name`, `pinyin`, `meridian_code`, `meridian_name`, `meridian_english`, `model_id`, `body_area`, `standard_location`, `child_location`, `child_description`, `safety_tip`, `source_name`, `source_link`, `position_x`, `position_y`, `position_z`, `sort_order`, `enabled`) VALUES ('LI-2', 2, '二间', 'Erjian', 'LI', '手阳明大肠经', 'Large Intestine Meridian', 'ig2', '手腕部', '在手指，第2掌指关节桡侧远端赤白肉际处。', '转动3D小铜人，看向手部、腕部。在手腕部找到“二间星”的发光点，点一下就完成观察。', 'LI-2是二间的星点编号。记住编号和手阳明大肠经，就找到了它的文化档案。', '只看3D铜人和文化图卡，不做身体操作；有问题请告诉老师或家长。', 'GB/T 12346-2021《经穴名称与定位》', 'https://openstd.samr.gov.cn/bzgk/std/newGbInfo?hcno=397548AE7248D3D87DD15E0AB8107185', 29.332201993135634, -14.700000000000307, 2.8000000000000007, 13, 1) ON DUPLICATE KEY UPDATE `point_number`=VALUES(`point_number`), `name`=VALUES(`name`), `pinyin`=VALUES(`pinyin`), `meridian_code`=VALUES(`meridian_code`), `meridian_name`=VALUES(`meridian_name`), `meridian_english`=VALUES(`meridian_english`), `model_id`=VALUES(`model_id`), `body_area`=VALUES(`body_area`), `standard_location`=VALUES(`standard_location`), `child_location`=VALUES(`child_location`), `child_description`=VALUES(`child_description`), `safety_tip`=VALUES(`safety_tip`), `source_name`=VALUES(`source_name`), `source_link`=VALUES(`source_link`), `position_x`=VALUES(`position_x`), `position_y`=VALUES(`position_y`), `position_z`=VALUES(`position_z`), `sort_order`=VALUES(`sort_order`), `enabled`=VALUES(`enabled`);
INSERT INTO `acupoint_knowledge` (`code`, `point_number`, `name`, `pinyin`, `meridian_code`, `meridian_name`, `meridian_english`, `model_id`, `body_area`, `standard_location`, `child_location`, `child_description`, `safety_tip`, `source_name`, `source_link`, `position_x`, `position_y`, `position_z`, `sort_order`, `enabled`) VALUES ('LI-3', 3, '三间', 'Sanjian', 'LI', '手阳明大肠经', 'Large Intestine Meridian', 'ig3', '手腕部', '在手背，第2掌指关节桡侧近端凹陷中。', '转动3D小铜人，看向手部、腕部。在手腕部找到“三间星”的发光点，点一下就完成观察。', '在手腕部的星点档案里，三间和手阳明大肠经站在同一条路线上。', '只看3D铜人和文化图卡，不做身体操作；有问题请告诉老师或家长。', 'GB/T 12346-2021《经穴名称与定位》', 'https://openstd.samr.gov.cn/bzgk/std/newGbInfo?hcno=397548AE7248D3D87DD15E0AB8107185', 29.532201993135637, -12.200000000000315, 1.7999999999999998, 14, 1) ON DUPLICATE KEY UPDATE `point_number`=VALUES(`point_number`), `name`=VALUES(`name`), `pinyin`=VALUES(`pinyin`), `meridian_code`=VALUES(`meridian_code`), `meridian_name`=VALUES(`meridian_name`), `meridian_english`=VALUES(`meridian_english`), `model_id`=VALUES(`model_id`), `body_area`=VALUES(`body_area`), `standard_location`=VALUES(`standard_location`), `child_location`=VALUES(`child_location`), `child_description`=VALUES(`child_description`), `safety_tip`=VALUES(`safety_tip`), `source_name`=VALUES(`source_name`), `source_link`=VALUES(`source_link`), `position_x`=VALUES(`position_x`), `position_y`=VALUES(`position_y`), `position_z`=VALUES(`position_z`), `sort_order`=VALUES(`sort_order`), `enabled`=VALUES(`enabled`);
INSERT INTO `acupoint_knowledge` (`code`, `point_number`, `name`, `pinyin`, `meridian_code`, `meridian_name`, `meridian_english`, `model_id`, `body_area`, `standard_location`, `child_location`, `child_description`, `safety_tip`, `source_name`, `source_link`, `position_x`, `position_y`, `position_z`, `sort_order`, `enabled`) VALUES ('LI-4', 4, '合谷', 'He Gu', 'LI', '手阳明大肠经', 'Large Intestine Meridian', 'ig4', '手腕部', '在手背，第1掌骨和第2掌骨之间，约平第2掌骨桡侧的中点。', '转动3D小铜人，看向手部、腕部。在手腕部找到“合谷星”的发光点，点一下就完成观察。', '合谷对小侦探说：“请把我放进手阳明大肠经档案。我的地图标签是手腕部。”', '只看3D铜人和文化图卡，不做身体操作；有问题请告诉老师或家长。', 'GB/T 12346-2021《经穴名称与定位》', 'https://openstd.samr.gov.cn/bzgk/std/newGbInfo?hcno=397548AE7248D3D87DD15E0AB8107185', 29.532201993135637, -10.500000000000322, 0.39999999999999936, 15, 1) ON DUPLICATE KEY UPDATE `point_number`=VALUES(`point_number`), `name`=VALUES(`name`), `pinyin`=VALUES(`pinyin`), `meridian_code`=VALUES(`meridian_code`), `meridian_name`=VALUES(`meridian_name`), `meridian_english`=VALUES(`meridian_english`), `model_id`=VALUES(`model_id`), `body_area`=VALUES(`body_area`), `standard_location`=VALUES(`standard_location`), `child_location`=VALUES(`child_location`), `child_description`=VALUES(`child_description`), `safety_tip`=VALUES(`safety_tip`), `source_name`=VALUES(`source_name`), `source_link`=VALUES(`source_link`), `position_x`=VALUES(`position_x`), `position_y`=VALUES(`position_y`), `position_z`=VALUES(`position_z`), `sort_order`=VALUES(`sort_order`), `enabled`=VALUES(`enabled`);
INSERT INTO `acupoint_knowledge` (`code`, `point_number`, `name`, `pinyin`, `meridian_code`, `meridian_name`, `meridian_english`, `model_id`, `body_area`, `standard_location`, `child_location`, `child_description`, `safety_tip`, `source_name`, `source_link`, `position_x`, `position_y`, `position_z`, `sort_order`, `enabled`) VALUES ('LI-5', 5, '阳谿', 'Yangxi', 'LI', '手阳明大肠经', 'Large Intestine Meridian', 'ig5', '手腕部', '在腕后外侧，腕背侧远端横纹桡侧，桡骨茎突远端，解剖学“鼻烟窝”凹陷中。', '转动3D小铜人，看向手部、腕部。在手腕部找到“阳谿星”的发光点，点一下就完成观察。', '今天的星光路牌叫阳谿。它不是按钮，而是帮我们读懂手阳明大肠经的文化标记。', '只看3D铜人和文化图卡，不做身体操作；有问题请告诉老师或家长。', 'GB/T 12346-2021《经穴名称与定位》', 'https://openstd.samr.gov.cn/bzgk/std/newGbInfo?hcno=397548AE7248D3D87DD15E0AB8107185', 28.33220199313562, -6.800000000000335, 0.39999999999999925, 16, 1) ON DUPLICATE KEY UPDATE `point_number`=VALUES(`point_number`), `name`=VALUES(`name`), `pinyin`=VALUES(`pinyin`), `meridian_code`=VALUES(`meridian_code`), `meridian_name`=VALUES(`meridian_name`), `meridian_english`=VALUES(`meridian_english`), `model_id`=VALUES(`model_id`), `body_area`=VALUES(`body_area`), `standard_location`=VALUES(`standard_location`), `child_location`=VALUES(`child_location`), `child_description`=VALUES(`child_description`), `safety_tip`=VALUES(`safety_tip`), `source_name`=VALUES(`source_name`), `source_link`=VALUES(`source_link`), `position_x`=VALUES(`position_x`), `position_y`=VALUES(`position_y`), `position_z`=VALUES(`position_z`), `sort_order`=VALUES(`sort_order`), `enabled`=VALUES(`enabled`);
INSERT INTO `acupoint_knowledge` (`code`, `point_number`, `name`, `pinyin`, `meridian_code`, `meridian_name`, `meridian_english`, `model_id`, `body_area`, `standard_location`, `child_location`, `child_description`, `safety_tip`, `source_name`, `source_link`, `position_x`, `position_y`, `position_z`, `sort_order`, `enabled`) VALUES ('LI-6', 6, '偏歴', 'Pianli', 'LI', '手阳明大肠经', 'Large Intestine Meridian', 'ig6', '手腕部', '在前臂后外侧，腕背侧远端横纹上3寸，阳溪（LI5）与曲池（LI11）连线上。注：阳溪至曲池连线的下1/4与上3/4交点处。', '转动3D小铜人，看向手部、腕部。在手腕部找到“偏歴星”的发光点，点一下就完成观察。', '小侦探找到了偏歴。档案上写着“手阳明大肠经”，它的地图区域是手腕部。', '只看3D铜人和文化图卡，不做身体操作；有问题请告诉老师或家长。', 'GB/T 12346-2021《经穴名称与定位》', 'https://openstd.samr.gov.cn/bzgk/std/newGbInfo?hcno=397548AE7248D3D87DD15E0AB8107185', 28.032201993135615, -0.3000000000003421, -3.8000000000000025, 17, 1) ON DUPLICATE KEY UPDATE `point_number`=VALUES(`point_number`), `name`=VALUES(`name`), `pinyin`=VALUES(`pinyin`), `meridian_code`=VALUES(`meridian_code`), `meridian_name`=VALUES(`meridian_name`), `meridian_english`=VALUES(`meridian_english`), `model_id`=VALUES(`model_id`), `body_area`=VALUES(`body_area`), `standard_location`=VALUES(`standard_location`), `child_location`=VALUES(`child_location`), `child_description`=VALUES(`child_description`), `safety_tip`=VALUES(`safety_tip`), `source_name`=VALUES(`source_name`), `source_link`=VALUES(`source_link`), `position_x`=VALUES(`position_x`), `position_y`=VALUES(`position_y`), `position_z`=VALUES(`position_z`), `sort_order`=VALUES(`sort_order`), `enabled`=VALUES(`enabled`);
INSERT INTO `acupoint_knowledge` (`code`, `point_number`, `name`, `pinyin`, `meridian_code`, `meridian_name`, `meridian_english`, `model_id`, `body_area`, `standard_location`, `child_location`, `child_description`, `safety_tip`, `source_name`, `source_link`, `position_x`, `position_y`, `position_z`, `sort_order`, `enabled`) VALUES ('LI-7', 7, '温溜', 'Wenliu', 'LI', '手阳明大肠经', 'Large Intestine Meridian', 'ig7', '手腕部', '在前臂后外侧，腕背侧远端横纹上5寸，阳溪（LI5）与曲池（LI11）连线上。', '转动3D小铜人，看向手部、腕部。在手腕部找到“温溜星”的发光点，点一下就完成观察。', '在手腕部的星点档案里，温溜和手阳明大肠经站在同一条路线上。', '只看3D铜人和文化图卡，不做身体操作；有问题请告诉老师或家长。', 'GB/T 12346-2021《经穴名称与定位》', 'https://openstd.samr.gov.cn/bzgk/std/newGbInfo?hcno=397548AE7248D3D87DD15E0AB8107185', 27.832201993135612, 4.399999999999659, -6.399999999999994, 18, 1) ON DUPLICATE KEY UPDATE `point_number`=VALUES(`point_number`), `name`=VALUES(`name`), `pinyin`=VALUES(`pinyin`), `meridian_code`=VALUES(`meridian_code`), `meridian_name`=VALUES(`meridian_name`), `meridian_english`=VALUES(`meridian_english`), `model_id`=VALUES(`model_id`), `body_area`=VALUES(`body_area`), `standard_location`=VALUES(`standard_location`), `child_location`=VALUES(`child_location`), `child_description`=VALUES(`child_description`), `safety_tip`=VALUES(`safety_tip`), `source_name`=VALUES(`source_name`), `source_link`=VALUES(`source_link`), `position_x`=VALUES(`position_x`), `position_y`=VALUES(`position_y`), `position_z`=VALUES(`position_z`), `sort_order`=VALUES(`sort_order`), `enabled`=VALUES(`enabled`);
INSERT INTO `acupoint_knowledge` (`code`, `point_number`, `name`, `pinyin`, `meridian_code`, `meridian_name`, `meridian_english`, `model_id`, `body_area`, `standard_location`, `child_location`, `child_description`, `safety_tip`, `source_name`, `source_link`, `position_x`, `position_y`, `position_z`, `sort_order`, `enabled`) VALUES ('LI-8', 8, '下廉', 'Xialian', 'LI', '手阳明大肠经', 'Large Intestine Meridian', 'ig8', '前臂与肘部', '在前臂后外侧，肘横纹下4寸，阳溪（LI5）与曲池（LI11）连线上。注：上廉（LI9）下1寸。', '转动3D小铜人，看向上肢前臂、肘部。在前臂与肘部找到“下廉星”的发光点，点一下就完成观察。', '下廉是手阳明大肠经的星河门牌。它告诉我们：这条文化路线会经过前臂与肘部。', '只看3D铜人和文化图卡，不做身体操作；有问题请告诉老师或家长。', 'GB/T 12346-2021《经穴名称与定位》', 'https://openstd.samr.gov.cn/bzgk/std/newGbInfo?hcno=397548AE7248D3D87DD15E0AB8107185', 27.73220199313561, 9.69999999999964, -8.099999999999989, 19, 1) ON DUPLICATE KEY UPDATE `point_number`=VALUES(`point_number`), `name`=VALUES(`name`), `pinyin`=VALUES(`pinyin`), `meridian_code`=VALUES(`meridian_code`), `meridian_name`=VALUES(`meridian_name`), `meridian_english`=VALUES(`meridian_english`), `model_id`=VALUES(`model_id`), `body_area`=VALUES(`body_area`), `standard_location`=VALUES(`standard_location`), `child_location`=VALUES(`child_location`), `child_description`=VALUES(`child_description`), `safety_tip`=VALUES(`safety_tip`), `source_name`=VALUES(`source_name`), `source_link`=VALUES(`source_link`), `position_x`=VALUES(`position_x`), `position_y`=VALUES(`position_y`), `position_z`=VALUES(`position_z`), `sort_order`=VALUES(`sort_order`), `enabled`=VALUES(`enabled`);
INSERT INTO `acupoint_knowledge` (`code`, `point_number`, `name`, `pinyin`, `meridian_code`, `meridian_name`, `meridian_english`, `model_id`, `body_area`, `standard_location`, `child_location`, `child_description`, `safety_tip`, `source_name`, `source_link`, `position_x`, `position_y`, `position_z`, `sort_order`, `enabled`) VALUES ('LI-9', 9, '上廉', 'Shanglian', 'LI', '手阳明大肠经', 'Large Intestine Meridian', 'ig9', '前臂与肘部', '在前臂后外侧，肘横纹下3寸，阳溪（LI5）与曲池（LI11）连线上。', '转动3D小铜人，看向上肢前臂、肘部。在前臂与肘部找到“上廉星”的发光点，点一下就完成观察。', 'LI-9是上廉的星点编号。记住编号和手阳明大肠经，就找到了它的文化档案。', '只看3D铜人和文化图卡，不做身体操作；有问题请告诉老师或家长。', 'GB/T 12346-2021《经穴名称与定位》', 'https://openstd.samr.gov.cn/bzgk/std/newGbInfo?hcno=397548AE7248D3D87DD15E0AB8107185', 27.532201993135608, 11.999999999999632, -8.799999999999986, 20, 1) ON DUPLICATE KEY UPDATE `point_number`=VALUES(`point_number`), `name`=VALUES(`name`), `pinyin`=VALUES(`pinyin`), `meridian_code`=VALUES(`meridian_code`), `meridian_name`=VALUES(`meridian_name`), `meridian_english`=VALUES(`meridian_english`), `model_id`=VALUES(`model_id`), `body_area`=VALUES(`body_area`), `standard_location`=VALUES(`standard_location`), `child_location`=VALUES(`child_location`), `child_description`=VALUES(`child_description`), `safety_tip`=VALUES(`safety_tip`), `source_name`=VALUES(`source_name`), `source_link`=VALUES(`source_link`), `position_x`=VALUES(`position_x`), `position_y`=VALUES(`position_y`), `position_z`=VALUES(`position_z`), `sort_order`=VALUES(`sort_order`), `enabled`=VALUES(`enabled`);
INSERT INTO `acupoint_knowledge` (`code`, `point_number`, `name`, `pinyin`, `meridian_code`, `meridian_name`, `meridian_english`, `model_id`, `body_area`, `standard_location`, `child_location`, `child_description`, `safety_tip`, `source_name`, `source_link`, `position_x`, `position_y`, `position_z`, `sort_order`, `enabled`) VALUES ('LI-10', 10, '手三里', 'Shousanli', 'LI', '手阳明大肠经', 'Large Intestine Meridian', 'ig10', '前臂与肘部', '在前臂后外侧，肘横纹下2寸，阳溪（LI5）与曲池（LI11）连线上。', '转动3D小铜人，看向上肢前臂、肘部。在前臂与肘部找到“手三里星”的发光点，点一下就完成观察。', '身体文化地图上，手三里是前臂与肘部的一枚探案印章。它属于手阳明大肠经。', '只看3D铜人和文化图卡，不做身体操作；有问题请告诉老师或家长。', 'GB/T 12346-2021《经穴名称与定位》', 'https://openstd.samr.gov.cn/bzgk/std/newGbInfo?hcno=397548AE7248D3D87DD15E0AB8107185', 27.232201993135604, 14.299999999999624, -9.299999999999985, 21, 1) ON DUPLICATE KEY UPDATE `point_number`=VALUES(`point_number`), `name`=VALUES(`name`), `pinyin`=VALUES(`pinyin`), `meridian_code`=VALUES(`meridian_code`), `meridian_name`=VALUES(`meridian_name`), `meridian_english`=VALUES(`meridian_english`), `model_id`=VALUES(`model_id`), `body_area`=VALUES(`body_area`), `standard_location`=VALUES(`standard_location`), `child_location`=VALUES(`child_location`), `child_description`=VALUES(`child_description`), `safety_tip`=VALUES(`safety_tip`), `source_name`=VALUES(`source_name`), `source_link`=VALUES(`source_link`), `position_x`=VALUES(`position_x`), `position_y`=VALUES(`position_y`), `position_z`=VALUES(`position_z`), `sort_order`=VALUES(`sort_order`), `enabled`=VALUES(`enabled`);
INSERT INTO `acupoint_knowledge` (`code`, `point_number`, `name`, `pinyin`, `meridian_code`, `meridian_name`, `meridian_english`, `model_id`, `body_area`, `standard_location`, `child_location`, `child_description`, `safety_tip`, `source_name`, `source_link`, `position_x`, `position_y`, `position_z`, `sort_order`, `enabled`) VALUES ('LI-11', 11, '曲池', 'Quchi', 'LI', '手阳明大肠经', 'Large Intestine Meridian', 'ig11', '前臂与肘部', '在肘外侧，尺泽（LU5）与肱骨外上髁连线的中点处。注：屈肘90°，肘横纹外侧端外凹陷中。', '转动3D小铜人，看向上肢前臂、肘部。在前臂与肘部找到“曲池星”的发光点，点一下就完成观察。', 'LI-11是曲池的星点编号。记住编号和手阳明大肠经，就找到了它的文化档案。', '只看3D铜人和文化图卡，不做身体操作；有问题请告诉老师或家长。', 'GB/T 12346-2021《经穴名称与定位》', 'https://openstd.samr.gov.cn/bzgk/std/newGbInfo?hcno=397548AE7248D3D87DD15E0AB8107185', 27.0322019931356, 17.59999999999964, -8.799999999999986, 22, 1) ON DUPLICATE KEY UPDATE `point_number`=VALUES(`point_number`), `name`=VALUES(`name`), `pinyin`=VALUES(`pinyin`), `meridian_code`=VALUES(`meridian_code`), `meridian_name`=VALUES(`meridian_name`), `meridian_english`=VALUES(`meridian_english`), `model_id`=VALUES(`model_id`), `body_area`=VALUES(`body_area`), `standard_location`=VALUES(`standard_location`), `child_location`=VALUES(`child_location`), `child_description`=VALUES(`child_description`), `safety_tip`=VALUES(`safety_tip`), `source_name`=VALUES(`source_name`), `source_link`=VALUES(`source_link`), `position_x`=VALUES(`position_x`), `position_y`=VALUES(`position_y`), `position_z`=VALUES(`position_z`), `sort_order`=VALUES(`sort_order`), `enabled`=VALUES(`enabled`);
INSERT INTO `acupoint_knowledge` (`code`, `point_number`, `name`, `pinyin`, `meridian_code`, `meridian_name`, `meridian_english`, `model_id`, `body_area`, `standard_location`, `child_location`, `child_description`, `safety_tip`, `source_name`, `source_link`, `position_x`, `position_y`, `position_z`, `sort_order`, `enabled`) VALUES ('LI-12', 12, '肘髎', 'Zhouliao', 'LI', '手阳明大肠经', 'Large Intestine Meridian', 'ig12', '前臂与肘部', '在肘后外侧，肱骨外上髁上缘，髁上嵴的前缘。', '转动3D小铜人，看向上肢前臂、肘部。在前臂与肘部找到“肘髎星”的发光点，点一下就完成观察。', '小侦探找到了肘髎。档案上写着“手阳明大肠经”，它的地图区域是前臂与肘部。', '只看3D铜人和文化图卡，不做身体操作；有问题请告诉老师或家长。', 'GB/T 12346-2021《经穴名称与定位》', 'https://openstd.samr.gov.cn/bzgk/std/newGbInfo?hcno=397548AE7248D3D87DD15E0AB8107185', 26.632201993135595, 20.49999999999968, -8.599999999999987, 23, 1) ON DUPLICATE KEY UPDATE `point_number`=VALUES(`point_number`), `name`=VALUES(`name`), `pinyin`=VALUES(`pinyin`), `meridian_code`=VALUES(`meridian_code`), `meridian_name`=VALUES(`meridian_name`), `meridian_english`=VALUES(`meridian_english`), `model_id`=VALUES(`model_id`), `body_area`=VALUES(`body_area`), `standard_location`=VALUES(`standard_location`), `child_location`=VALUES(`child_location`), `child_description`=VALUES(`child_description`), `safety_tip`=VALUES(`safety_tip`), `source_name`=VALUES(`source_name`), `source_link`=VALUES(`source_link`), `position_x`=VALUES(`position_x`), `position_y`=VALUES(`position_y`), `position_z`=VALUES(`position_z`), `sort_order`=VALUES(`sort_order`), `enabled`=VALUES(`enabled`);
INSERT INTO `acupoint_knowledge` (`code`, `point_number`, `name`, `pinyin`, `meridian_code`, `meridian_name`, `meridian_english`, `model_id`, `body_area`, `standard_location`, `child_location`, `child_description`, `safety_tip`, `source_name`, `source_link`, `position_x`, `position_y`, `position_z`, `sort_order`, `enabled`) VALUES ('LI-13', 13, '手五里', 'Shouwuli', 'LI', '手阳明大肠经', 'Large Intestine Meridian', 'ig13', '前臂与肘部', '在臂外侧，肘横纹上3寸，曲池（LI11）与肩髃（LI15）连线上。', '转动3D小铜人，看向上肢前臂、肘部。在前臂与肘部找到“手五里星”的发光点，点一下就完成观察。', '小侦探找到了手五里。档案上写着“手阳明大肠经”，它的地图区域是前臂与肘部。', '只看3D铜人和文化图卡，不做身体操作；有问题请告诉老师或家长。', 'GB/T 12346-2021《经穴名称与定位》', 'https://openstd.samr.gov.cn/bzgk/std/newGbInfo?hcno=397548AE7248D3D87DD15E0AB8107185', 26.432201993135592, 23.499999999999723, -9.299999999999985, 24, 1) ON DUPLICATE KEY UPDATE `point_number`=VALUES(`point_number`), `name`=VALUES(`name`), `pinyin`=VALUES(`pinyin`), `meridian_code`=VALUES(`meridian_code`), `meridian_name`=VALUES(`meridian_name`), `meridian_english`=VALUES(`meridian_english`), `model_id`=VALUES(`model_id`), `body_area`=VALUES(`body_area`), `standard_location`=VALUES(`standard_location`), `child_location`=VALUES(`child_location`), `child_description`=VALUES(`child_description`), `safety_tip`=VALUES(`safety_tip`), `source_name`=VALUES(`source_name`), `source_link`=VALUES(`source_link`), `position_x`=VALUES(`position_x`), `position_y`=VALUES(`position_y`), `position_z`=VALUES(`position_z`), `sort_order`=VALUES(`sort_order`), `enabled`=VALUES(`enabled`);
INSERT INTO `acupoint_knowledge` (`code`, `point_number`, `name`, `pinyin`, `meridian_code`, `meridian_name`, `meridian_english`, `model_id`, `body_area`, `standard_location`, `child_location`, `child_description`, `safety_tip`, `source_name`, `source_link`, `position_x`, `position_y`, `position_z`, `sort_order`, `enabled`) VALUES ('LI-14', 14, '臂臑', 'Binao', 'LI', '手阳明大肠经', 'Large Intestine Meridian', 'ig14', '肩臂部', '在臂外侧，曲池（LI11）与肩髃（LI15）连线上，三角肌前缘处。注：约曲池上7寸。', '转动3D小铜人，看向上臂、肩部。在肩臂部找到“臂臑星”的发光点，点一下就完成观察。', '臂臑带着一张“手阳明大肠经”路线卡。把它收进档案，再认一认肩臂部。', '只看3D铜人和文化图卡，不做身体操作；有问题请告诉老师或家长。', 'GB/T 12346-2021《经穴名称与定位》', 'https://openstd.samr.gov.cn/bzgk/std/newGbInfo?hcno=397548AE7248D3D87DD15E0AB8107185', 24.73220199313557, 33.29999999999986, -7.599999999999991, 25, 1) ON DUPLICATE KEY UPDATE `point_number`=VALUES(`point_number`), `name`=VALUES(`name`), `pinyin`=VALUES(`pinyin`), `meridian_code`=VALUES(`meridian_code`), `meridian_name`=VALUES(`meridian_name`), `meridian_english`=VALUES(`meridian_english`), `model_id`=VALUES(`model_id`), `body_area`=VALUES(`body_area`), `standard_location`=VALUES(`standard_location`), `child_location`=VALUES(`child_location`), `child_description`=VALUES(`child_description`), `safety_tip`=VALUES(`safety_tip`), `source_name`=VALUES(`source_name`), `source_link`=VALUES(`source_link`), `position_x`=VALUES(`position_x`), `position_y`=VALUES(`position_y`), `position_z`=VALUES(`position_z`), `sort_order`=VALUES(`sort_order`), `enabled`=VALUES(`enabled`);
INSERT INTO `acupoint_knowledge` (`code`, `point_number`, `name`, `pinyin`, `meridian_code`, `meridian_name`, `meridian_english`, `model_id`, `body_area`, `standard_location`, `child_location`, `child_description`, `safety_tip`, `source_name`, `source_link`, `position_x`, `position_y`, `position_z`, `sort_order`, `enabled`) VALUES ('LI-15', 15, '肩髃', 'Jianyu', 'LI', '手阳明大肠经', 'Large Intestine Meridian', 'ig15', '肩臂部', '在肩带部，肩峰外侧缘前端与肱骨大结节两骨间凹陷中。注：臂外展时肩峰外侧缘前后端呈两个凹陷，前一较深凹陷为本穴。', '转动3D小铜人，看向上臂、肩部。在肩臂部找到“肩髃星”的发光点，点一下就完成观察。', '肩髃带着一张“手阳明大肠经”路线卡。把它收进档案，再认一认肩臂部。', '只看3D铜人和文化图卡，不做身体操作；有问题请告诉老师或家长。', 'GB/T 12346-2021《经穴名称与定位》', 'https://openstd.samr.gov.cn/bzgk/std/newGbInfo?hcno=397548AE7248D3D87DD15E0AB8107185', 20.432201993135507, 47.20000000000006, -5, 26, 1) ON DUPLICATE KEY UPDATE `point_number`=VALUES(`point_number`), `name`=VALUES(`name`), `pinyin`=VALUES(`pinyin`), `meridian_code`=VALUES(`meridian_code`), `meridian_name`=VALUES(`meridian_name`), `meridian_english`=VALUES(`meridian_english`), `model_id`=VALUES(`model_id`), `body_area`=VALUES(`body_area`), `standard_location`=VALUES(`standard_location`), `child_location`=VALUES(`child_location`), `child_description`=VALUES(`child_description`), `safety_tip`=VALUES(`safety_tip`), `source_name`=VALUES(`source_name`), `source_link`=VALUES(`source_link`), `position_x`=VALUES(`position_x`), `position_y`=VALUES(`position_y`), `position_z`=VALUES(`position_z`), `sort_order`=VALUES(`sort_order`), `enabled`=VALUES(`enabled`);
INSERT INTO `acupoint_knowledge` (`code`, `point_number`, `name`, `pinyin`, `meridian_code`, `meridian_name`, `meridian_english`, `model_id`, `body_area`, `standard_location`, `child_location`, `child_description`, `safety_tip`, `source_name`, `source_link`, `position_x`, `position_y`, `position_z`, `sort_order`, `enabled`) VALUES ('LI-16', 16, '巨骨', 'Jugu', 'LI', '手阳明大肠经', 'Large Intestine Meridian', 'ig16', '肩臂部', '在肩带部，锁骨肩峰端与肩胛冈之间凹陷中。注：冈上窝外端两骨间凹陷中。', '转动3D小铜人，看向上臂、肩部。在肩臂部找到“巨骨星”的发光点，点一下就完成观察。', '巨骨对小侦探说：“请把我放进手阳明大肠经档案。我的地图标签是肩臂部。”', '只看3D铜人和文化图卡，不做身体操作；有问题请告诉老师或家长。', 'GB/T 12346-2021《经穴名称与定位》', 'https://openstd.samr.gov.cn/bzgk/std/newGbInfo?hcno=397548AE7248D3D87DD15E0AB8107185', 18.132201993135475, 48.80000000000008, -6.499999999999995, 27, 1) ON DUPLICATE KEY UPDATE `point_number`=VALUES(`point_number`), `name`=VALUES(`name`), `pinyin`=VALUES(`pinyin`), `meridian_code`=VALUES(`meridian_code`), `meridian_name`=VALUES(`meridian_name`), `meridian_english`=VALUES(`meridian_english`), `model_id`=VALUES(`model_id`), `body_area`=VALUES(`body_area`), `standard_location`=VALUES(`standard_location`), `child_location`=VALUES(`child_location`), `child_description`=VALUES(`child_description`), `safety_tip`=VALUES(`safety_tip`), `source_name`=VALUES(`source_name`), `source_link`=VALUES(`source_link`), `position_x`=VALUES(`position_x`), `position_y`=VALUES(`position_y`), `position_z`=VALUES(`position_z`), `sort_order`=VALUES(`sort_order`), `enabled`=VALUES(`enabled`);
INSERT INTO `acupoint_knowledge` (`code`, `point_number`, `name`, `pinyin`, `meridian_code`, `meridian_name`, `meridian_english`, `model_id`, `body_area`, `standard_location`, `child_location`, `child_description`, `safety_tip`, `source_name`, `source_link`, `position_x`, `position_y`, `position_z`, `sort_order`, `enabled`) VALUES ('LI-17', 17, '天鼎', 'Tianding', 'LI', '手阳明大肠经', 'Large Intestine Meridian', 'ig17', '头面与颈部', '在颈前部，横平环状软骨，胸锁乳突肌后缘。注：扶突（LI18）直下，横平水突（ST10）。', '转动3D小铜人，看向颈面部。在头面与颈部找到“天鼎星”的发光点，点一下就完成观察。', '身体文化地图上，天鼎是头面与颈部的一枚星河门牌。它属于手阳明大肠经。', '只看3D铜人和文化图卡，不做身体操作；有问题请告诉老师或家长。', 'GB/T 12346-2021《经穴名称与定位》', 'https://openstd.samr.gov.cn/bzgk/std/newGbInfo?hcno=397548AE7248D3D87DD15E0AB8107185', 5.532201993135482, 54.10000000000016, -4.0000000000000036, 28, 1) ON DUPLICATE KEY UPDATE `point_number`=VALUES(`point_number`), `name`=VALUES(`name`), `pinyin`=VALUES(`pinyin`), `meridian_code`=VALUES(`meridian_code`), `meridian_name`=VALUES(`meridian_name`), `meridian_english`=VALUES(`meridian_english`), `model_id`=VALUES(`model_id`), `body_area`=VALUES(`body_area`), `standard_location`=VALUES(`standard_location`), `child_location`=VALUES(`child_location`), `child_description`=VALUES(`child_description`), `safety_tip`=VALUES(`safety_tip`), `source_name`=VALUES(`source_name`), `source_link`=VALUES(`source_link`), `position_x`=VALUES(`position_x`), `position_y`=VALUES(`position_y`), `position_z`=VALUES(`position_z`), `sort_order`=VALUES(`sort_order`), `enabled`=VALUES(`enabled`);
INSERT INTO `acupoint_knowledge` (`code`, `point_number`, `name`, `pinyin`, `meridian_code`, `meridian_name`, `meridian_english`, `model_id`, `body_area`, `standard_location`, `child_location`, `child_description`, `safety_tip`, `source_name`, `source_link`, `position_x`, `position_y`, `position_z`, `sort_order`, `enabled`) VALUES ('LI-18', 18, '扶突', 'Futu', 'LI', '手阳明大肠经', 'Large Intestine Meridian', 'ig18', '头面与颈部', '在颈前部，横平甲状软骨上缘（约相当于喉结处），胸锁乳突肌前、后缘中间。', '转动3D小铜人，看向颈面部。在头面与颈部找到“扶突星”的发光点，点一下就完成观察。', '扶突的档案有两个关键词：头面与颈部和手阳明大肠经。把它们连起来，线索就完整了。', '只看3D铜人和文化图卡，不做身体操作；有问题请告诉老师或家长。', 'GB/T 12346-2021《经穴名称与定位》', 'https://openstd.samr.gov.cn/bzgk/std/newGbInfo?hcno=397548AE7248D3D87DD15E0AB8107185', 5.132201993135483, 56.100000000000186, -3.600000000000003, 29, 1) ON DUPLICATE KEY UPDATE `point_number`=VALUES(`point_number`), `name`=VALUES(`name`), `pinyin`=VALUES(`pinyin`), `meridian_code`=VALUES(`meridian_code`), `meridian_name`=VALUES(`meridian_name`), `meridian_english`=VALUES(`meridian_english`), `model_id`=VALUES(`model_id`), `body_area`=VALUES(`body_area`), `standard_location`=VALUES(`standard_location`), `child_location`=VALUES(`child_location`), `child_description`=VALUES(`child_description`), `safety_tip`=VALUES(`safety_tip`), `source_name`=VALUES(`source_name`), `source_link`=VALUES(`source_link`), `position_x`=VALUES(`position_x`), `position_y`=VALUES(`position_y`), `position_z`=VALUES(`position_z`), `sort_order`=VALUES(`sort_order`), `enabled`=VALUES(`enabled`);
INSERT INTO `acupoint_knowledge` (`code`, `point_number`, `name`, `pinyin`, `meridian_code`, `meridian_name`, `meridian_english`, `model_id`, `body_area`, `standard_location`, `child_location`, `child_description`, `safety_tip`, `source_name`, `source_link`, `position_x`, `position_y`, `position_z`, `sort_order`, `enabled`) VALUES ('LI-19', 19, '口禾髎', 'Kouheliao', 'LI', '手阳明大肠经', 'Large Intestine Meridian', 'ig19', '头面与颈部', '在面部，横平人中沟上1/3与下2/3交点，鼻孔外缘直下。注：水沟（GV26）旁开0.5寸。', '转动3D小铜人，看向颈面部。在头面与颈部找到“口禾髎星”的发光点，点一下就完成观察。', '点亮口禾髎后，头面与颈部的地图多了一颗星。它是手阳明大肠经路线的一站。', '只看3D铜人和文化图卡，不做身体操作；有问题请告诉老师或家长。', 'GB/T 12346-2021《经穴名称与定位》', 'https://openstd.samr.gov.cn/bzgk/std/newGbInfo?hcno=397548AE7248D3D87DD15E0AB8107185', 0.9322019931354847, 62.400000000000276, 4.899999999999998, 30, 1) ON DUPLICATE KEY UPDATE `point_number`=VALUES(`point_number`), `name`=VALUES(`name`), `pinyin`=VALUES(`pinyin`), `meridian_code`=VALUES(`meridian_code`), `meridian_name`=VALUES(`meridian_name`), `meridian_english`=VALUES(`meridian_english`), `model_id`=VALUES(`model_id`), `body_area`=VALUES(`body_area`), `standard_location`=VALUES(`standard_location`), `child_location`=VALUES(`child_location`), `child_description`=VALUES(`child_description`), `safety_tip`=VALUES(`safety_tip`), `source_name`=VALUES(`source_name`), `source_link`=VALUES(`source_link`), `position_x`=VALUES(`position_x`), `position_y`=VALUES(`position_y`), `position_z`=VALUES(`position_z`), `sort_order`=VALUES(`sort_order`), `enabled`=VALUES(`enabled`);
INSERT INTO `acupoint_knowledge` (`code`, `point_number`, `name`, `pinyin`, `meridian_code`, `meridian_name`, `meridian_english`, `model_id`, `body_area`, `standard_location`, `child_location`, `child_description`, `safety_tip`, `source_name`, `source_link`, `position_x`, `position_y`, `position_z`, `sort_order`, `enabled`) VALUES ('LI-20', 20, '迎香', 'Yingxiang', 'LI', '手阳明大肠经', 'Large Intestine Meridian', 'ig20', '头面与颈部', '在面部，鼻翼外缘中点旁，鼻唇沟中。', '转动3D小铜人，看向颈面部。在头面与颈部找到“迎香星”的发光点，点一下就完成观察。', '小侦探找到了迎香。档案上写着“手阳明大肠经”，它的地图区域是头面与颈部。', '只看3D铜人和文化图卡，不做身体操作；有问题请告诉老师或家长。', 'GB/T 12346-2021《经穴名称与定位》', 'https://openstd.samr.gov.cn/bzgk/std/newGbInfo?hcno=397548AE7248D3D87DD15E0AB8107185', 1.9322019931354855, 62.90000000000028, 4.3, 31, 1) ON DUPLICATE KEY UPDATE `point_number`=VALUES(`point_number`), `name`=VALUES(`name`), `pinyin`=VALUES(`pinyin`), `meridian_code`=VALUES(`meridian_code`), `meridian_name`=VALUES(`meridian_name`), `meridian_english`=VALUES(`meridian_english`), `model_id`=VALUES(`model_id`), `body_area`=VALUES(`body_area`), `standard_location`=VALUES(`standard_location`), `child_location`=VALUES(`child_location`), `child_description`=VALUES(`child_description`), `safety_tip`=VALUES(`safety_tip`), `source_name`=VALUES(`source_name`), `source_link`=VALUES(`source_link`), `position_x`=VALUES(`position_x`), `position_y`=VALUES(`position_y`), `position_z`=VALUES(`position_z`), `sort_order`=VALUES(`sort_order`), `enabled`=VALUES(`enabled`);
INSERT INTO `acupoint_knowledge` (`code`, `point_number`, `name`, `pinyin`, `meridian_code`, `meridian_name`, `meridian_english`, `model_id`, `body_area`, `standard_location`, `child_location`, `child_description`, `safety_tip`, `source_name`, `source_link`, `position_x`, `position_y`, `position_z`, `sort_order`, `enabled`) VALUES ('ST-1', 1, '承泣', 'Chengqi', 'ST', '足阳明胃经', 'Stomach Meridian', 'e1', '头面与颈部', '在面部，眼球与眶下缘之间，瞳孔直下。', '转动3D小铜人，看向面部。在头面与颈部找到“承泣星”的发光点，点一下就完成观察。', '小铜人把承泣标成ST-1。这枚星光路牌帮我们记住头面与颈部和足阳明胃经。', '只看3D铜人和文化图卡，不做身体操作；有问题请告诉老师或家长。', 'GB/T 12346-2021《经穴名称与定位》', 'https://openstd.samr.gov.cn/bzgk/std/newGbInfo?hcno=397548AE7248D3D87DD15E0AB8107185', -2.9677980068645167, 66.70000000000014, 3, 32, 1) ON DUPLICATE KEY UPDATE `point_number`=VALUES(`point_number`), `name`=VALUES(`name`), `pinyin`=VALUES(`pinyin`), `meridian_code`=VALUES(`meridian_code`), `meridian_name`=VALUES(`meridian_name`), `meridian_english`=VALUES(`meridian_english`), `model_id`=VALUES(`model_id`), `body_area`=VALUES(`body_area`), `standard_location`=VALUES(`standard_location`), `child_location`=VALUES(`child_location`), `child_description`=VALUES(`child_description`), `safety_tip`=VALUES(`safety_tip`), `source_name`=VALUES(`source_name`), `source_link`=VALUES(`source_link`), `position_x`=VALUES(`position_x`), `position_y`=VALUES(`position_y`), `position_z`=VALUES(`position_z`), `sort_order`=VALUES(`sort_order`), `enabled`=VALUES(`enabled`);
INSERT INTO `acupoint_knowledge` (`code`, `point_number`, `name`, `pinyin`, `meridian_code`, `meridian_name`, `meridian_english`, `model_id`, `body_area`, `standard_location`, `child_location`, `child_description`, `safety_tip`, `source_name`, `source_link`, `position_x`, `position_y`, `position_z`, `sort_order`, `enabled`) VALUES ('ST-2', 2, '四白', 'Sibai', 'ST', '足阳明胃经', 'Stomach Meridian', 'e2', '头面与颈部', '在面部，眶下孔处。', '转动3D小铜人，看向面部。在头面与颈部找到“四白星”的发光点，点一下就完成观察。', '四白带着一张“足阳明胃经”路线卡。把它收进档案，再认一认头面与颈部。', '只看3D铜人和文化图卡，不做身体操作；有问题请告诉老师或家长。', 'GB/T 12346-2021《经穴名称与定位》', 'https://openstd.samr.gov.cn/bzgk/std/newGbInfo?hcno=397548AE7248D3D87DD15E0AB8107185', -2.9677980068645167, 66.00000000000018, 3.2, 33, 1) ON DUPLICATE KEY UPDATE `point_number`=VALUES(`point_number`), `name`=VALUES(`name`), `pinyin`=VALUES(`pinyin`), `meridian_code`=VALUES(`meridian_code`), `meridian_name`=VALUES(`meridian_name`), `meridian_english`=VALUES(`meridian_english`), `model_id`=VALUES(`model_id`), `body_area`=VALUES(`body_area`), `standard_location`=VALUES(`standard_location`), `child_location`=VALUES(`child_location`), `child_description`=VALUES(`child_description`), `safety_tip`=VALUES(`safety_tip`), `source_name`=VALUES(`source_name`), `source_link`=VALUES(`source_link`), `position_x`=VALUES(`position_x`), `position_y`=VALUES(`position_y`), `position_z`=VALUES(`position_z`), `sort_order`=VALUES(`sort_order`), `enabled`=VALUES(`enabled`);
INSERT INTO `acupoint_knowledge` (`code`, `point_number`, `name`, `pinyin`, `meridian_code`, `meridian_name`, `meridian_english`, `model_id`, `body_area`, `standard_location`, `child_location`, `child_description`, `safety_tip`, `source_name`, `source_link`, `position_x`, `position_y`, `position_z`, `sort_order`, `enabled`) VALUES ('ST-3', 3, '巨髎', 'Juliao', 'ST', '足阳明胃经', 'Stomach Meridian', 'e3', '头面与颈部', '在面部，横平鼻翼下缘，瞳孔直下。', '转动3D小铜人，看向面部。在头面与颈部找到“巨髎星”的发光点，点一下就完成观察。', '身体文化地图上，巨髎是头面与颈部的一枚星光路牌。它属于足阳明胃经。', '只看3D铜人和文化图卡，不做身体操作；有问题请告诉老师或家长。', 'GB/T 12346-2021《经穴名称与定位》', 'https://openstd.samr.gov.cn/bzgk/std/newGbInfo?hcno=397548AE7248D3D87DD15E0AB8107185', -2.8677980068645166, 63.700000000000294, 3.8000000000000007, 34, 1) ON DUPLICATE KEY UPDATE `point_number`=VALUES(`point_number`), `name`=VALUES(`name`), `pinyin`=VALUES(`pinyin`), `meridian_code`=VALUES(`meridian_code`), `meridian_name`=VALUES(`meridian_name`), `meridian_english`=VALUES(`meridian_english`), `model_id`=VALUES(`model_id`), `body_area`=VALUES(`body_area`), `standard_location`=VALUES(`standard_location`), `child_location`=VALUES(`child_location`), `child_description`=VALUES(`child_description`), `safety_tip`=VALUES(`safety_tip`), `source_name`=VALUES(`source_name`), `source_link`=VALUES(`source_link`), `position_x`=VALUES(`position_x`), `position_y`=VALUES(`position_y`), `position_z`=VALUES(`position_z`), `sort_order`=VALUES(`sort_order`), `enabled`=VALUES(`enabled`);
INSERT INTO `acupoint_knowledge` (`code`, `point_number`, `name`, `pinyin`, `meridian_code`, `meridian_name`, `meridian_english`, `model_id`, `body_area`, `standard_location`, `child_location`, `child_description`, `safety_tip`, `source_name`, `source_link`, `position_x`, `position_y`, `position_z`, `sort_order`, `enabled`) VALUES ('ST-4', 4, '地仓', 'Dicang', 'ST', '足阳明胃经', 'Stomach Meridian', 'e4', '头面与颈部', '在面部，口角旁开0.4寸。注：口角旁，在鼻唇沟或鼻唇沟延长线上。', '转动3D小铜人，看向面部。在头面与颈部找到“地仓星”的发光点，点一下就完成观察。', '身体文化地图上，地仓是头面与颈部的一枚探案印章。它属于足阳明胃经。', '只看3D铜人和文化图卡，不做身体操作；有问题请告诉老师或家长。', 'GB/T 12346-2021《经穴名称与定位》', 'https://openstd.samr.gov.cn/bzgk/std/newGbInfo?hcno=397548AE7248D3D87DD15E0AB8107185', -2.7677980068645165, 61.10000000000026, 4.1000000000000005, 35, 1) ON DUPLICATE KEY UPDATE `point_number`=VALUES(`point_number`), `name`=VALUES(`name`), `pinyin`=VALUES(`pinyin`), `meridian_code`=VALUES(`meridian_code`), `meridian_name`=VALUES(`meridian_name`), `meridian_english`=VALUES(`meridian_english`), `model_id`=VALUES(`model_id`), `body_area`=VALUES(`body_area`), `standard_location`=VALUES(`standard_location`), `child_location`=VALUES(`child_location`), `child_description`=VALUES(`child_description`), `safety_tip`=VALUES(`safety_tip`), `source_name`=VALUES(`source_name`), `source_link`=VALUES(`source_link`), `position_x`=VALUES(`position_x`), `position_y`=VALUES(`position_y`), `position_z`=VALUES(`position_z`), `sort_order`=VALUES(`sort_order`), `enabled`=VALUES(`enabled`);
INSERT INTO `acupoint_knowledge` (`code`, `point_number`, `name`, `pinyin`, `meridian_code`, `meridian_name`, `meridian_english`, `model_id`, `body_area`, `standard_location`, `child_location`, `child_description`, `safety_tip`, `source_name`, `source_link`, `position_x`, `position_y`, `position_z`, `sort_order`, `enabled`) VALUES ('ST-5', 5, '大迎', 'Daying', 'ST', '足阳明胃经', 'Stomach Meridian', 'e5', '头面与颈部', '在面部，下颌角前方，咬肌附着部的前缘凹陷中，面动脉搏动处。', '转动3D小铜人，看向面部。在头面与颈部找到“大迎星”的发光点，点一下就完成观察。', 'ST-5是大迎的星点编号。记住编号和足阳明胃经，就找到了它的文化档案。', '只看3D铜人和文化图卡，不做身体操作；有问题请告诉老师或家长。', 'GB/T 12346-2021《经穴名称与定位》', 'https://openstd.samr.gov.cn/bzgk/std/newGbInfo?hcno=397548AE7248D3D87DD15E0AB8107185', -3.367798006864517, 58.200000000000216, 2.4999999999999996, 36, 1) ON DUPLICATE KEY UPDATE `point_number`=VALUES(`point_number`), `name`=VALUES(`name`), `pinyin`=VALUES(`pinyin`), `meridian_code`=VALUES(`meridian_code`), `meridian_name`=VALUES(`meridian_name`), `meridian_english`=VALUES(`meridian_english`), `model_id`=VALUES(`model_id`), `body_area`=VALUES(`body_area`), `standard_location`=VALUES(`standard_location`), `child_location`=VALUES(`child_location`), `child_description`=VALUES(`child_description`), `safety_tip`=VALUES(`safety_tip`), `source_name`=VALUES(`source_name`), `source_link`=VALUES(`source_link`), `position_x`=VALUES(`position_x`), `position_y`=VALUES(`position_y`), `position_z`=VALUES(`position_z`), `sort_order`=VALUES(`sort_order`), `enabled`=VALUES(`enabled`);
INSERT INTO `acupoint_knowledge` (`code`, `point_number`, `name`, `pinyin`, `meridian_code`, `meridian_name`, `meridian_english`, `model_id`, `body_area`, `standard_location`, `child_location`, `child_description`, `safety_tip`, `source_name`, `source_link`, `position_x`, `position_y`, `position_z`, `sort_order`, `enabled`) VALUES ('ST-6', 6, '颊车', 'Jiache', 'ST', '足阳明胃经', 'Stomach Meridian', 'e6', '头面与颈部', '在面部，下颌角前上方一横指。注：闭口咬紧牙时咬肌隆起，放松时按之有凹陷处。', '转动3D小铜人，看向面部。在头面与颈部找到“颊车星”的发光点，点一下就完成观察。', '颊车是足阳明胃经的星光路牌。它告诉我们：这条文化路线会经过头面与颈部。', '只看3D铜人和文化图卡，不做身体操作；有问题请告诉老师或家长。', 'GB/T 12346-2021《经穴名称与定位》', 'https://openstd.samr.gov.cn/bzgk/std/newGbInfo?hcno=397548AE7248D3D87DD15E0AB8107185', -5.967798006864511, 61.30000000000026, -2.6000000000000028, 37, 1) ON DUPLICATE KEY UPDATE `point_number`=VALUES(`point_number`), `name`=VALUES(`name`), `pinyin`=VALUES(`pinyin`), `meridian_code`=VALUES(`meridian_code`), `meridian_name`=VALUES(`meridian_name`), `meridian_english`=VALUES(`meridian_english`), `model_id`=VALUES(`model_id`), `body_area`=VALUES(`body_area`), `standard_location`=VALUES(`standard_location`), `child_location`=VALUES(`child_location`), `child_description`=VALUES(`child_description`), `safety_tip`=VALUES(`safety_tip`), `source_name`=VALUES(`source_name`), `source_link`=VALUES(`source_link`), `position_x`=VALUES(`position_x`), `position_y`=VALUES(`position_y`), `position_z`=VALUES(`position_z`), `sort_order`=VALUES(`sort_order`), `enabled`=VALUES(`enabled`);
INSERT INTO `acupoint_knowledge` (`code`, `point_number`, `name`, `pinyin`, `meridian_code`, `meridian_name`, `meridian_english`, `model_id`, `body_area`, `standard_location`, `child_location`, `child_description`, `safety_tip`, `source_name`, `source_link`, `position_x`, `position_y`, `position_z`, `sort_order`, `enabled`) VALUES ('ST-7', 7, '下关', 'Xiaguan', 'ST', '足阳明胃经', 'Stomach Meridian', 'e7', '头面与颈部', '在面部，颧弓下缘中央与下颌切迹之间凹陷中。注：闭口，上关（GB3）直下，颧弓下缘凹陷中。', '转动3D小铜人，看向面部。在头面与颈部找到“下关星”的发光点，点一下就完成观察。', '今天的星河门牌叫下关。它不是按钮，而是帮我们读懂足阳明胃经的文化标记。', '只看3D铜人和文化图卡，不做身体操作；有问题请告诉老师或家长。', 'GB/T 12346-2021《经穴名称与定位》', 'https://openstd.samr.gov.cn/bzgk/std/newGbInfo?hcno=397548AE7248D3D87DD15E0AB8107185', -6.467798006864509, 64.20000000000029, -2.700000000000003, 38, 1) ON DUPLICATE KEY UPDATE `point_number`=VALUES(`point_number`), `name`=VALUES(`name`), `pinyin`=VALUES(`pinyin`), `meridian_code`=VALUES(`meridian_code`), `meridian_name`=VALUES(`meridian_name`), `meridian_english`=VALUES(`meridian_english`), `model_id`=VALUES(`model_id`), `body_area`=VALUES(`body_area`), `standard_location`=VALUES(`standard_location`), `child_location`=VALUES(`child_location`), `child_description`=VALUES(`child_description`), `safety_tip`=VALUES(`safety_tip`), `source_name`=VALUES(`source_name`), `source_link`=VALUES(`source_link`), `position_x`=VALUES(`position_x`), `position_y`=VALUES(`position_y`), `position_z`=VALUES(`position_z`), `sort_order`=VALUES(`sort_order`), `enabled`=VALUES(`enabled`);
INSERT INTO `acupoint_knowledge` (`code`, `point_number`, `name`, `pinyin`, `meridian_code`, `meridian_name`, `meridian_english`, `model_id`, `body_area`, `standard_location`, `child_location`, `child_description`, `safety_tip`, `source_name`, `source_link`, `position_x`, `position_y`, `position_z`, `sort_order`, `enabled`) VALUES ('ST-8', 8, '头维', 'Touwei', 'ST', '足阳明胃经', 'Stomach Meridian', 'e8', '头面与颈部', '在头部，额角发际直上0.5寸，头正中线旁开4.5寸。', '转动3D小铜人，看向面部。在头面与颈部找到“头维星”的发光点，点一下就完成观察。', '在头面与颈部的星点档案里，头维和足阳明胃经站在同一条路线上。', '只看3D铜人和文化图卡，不做身体操作；有问题请告诉老师或家长。', 'GB/T 12346-2021《经穴名称与定位》', 'https://openstd.samr.gov.cn/bzgk/std/newGbInfo?hcno=397548AE7248D3D87DD15E0AB8107185', -6.26779800686451, 71.89999999999985, -2.700000000000003, 39, 1) ON DUPLICATE KEY UPDATE `point_number`=VALUES(`point_number`), `name`=VALUES(`name`), `pinyin`=VALUES(`pinyin`), `meridian_code`=VALUES(`meridian_code`), `meridian_name`=VALUES(`meridian_name`), `meridian_english`=VALUES(`meridian_english`), `model_id`=VALUES(`model_id`), `body_area`=VALUES(`body_area`), `standard_location`=VALUES(`standard_location`), `child_location`=VALUES(`child_location`), `child_description`=VALUES(`child_description`), `safety_tip`=VALUES(`safety_tip`), `source_name`=VALUES(`source_name`), `source_link`=VALUES(`source_link`), `position_x`=VALUES(`position_x`), `position_y`=VALUES(`position_y`), `position_z`=VALUES(`position_z`), `sort_order`=VALUES(`sort_order`), `enabled`=VALUES(`enabled`);
INSERT INTO `acupoint_knowledge` (`code`, `point_number`, `name`, `pinyin`, `meridian_code`, `meridian_name`, `meridian_english`, `model_id`, `body_area`, `standard_location`, `child_location`, `child_description`, `safety_tip`, `source_name`, `source_link`, `position_x`, `position_y`, `position_z`, `sort_order`, `enabled`) VALUES ('ST-9', 9, '人迎', 'Renying', 'ST', '足阳明胃经', 'Stomach Meridian', 'e9', '头面与颈部', '在颈前部，横平甲状软骨上缘，胸锁乳突肌前缘，颈总动脉搏动处。', '转动3D小铜人，看向颈前部。在头面与颈部找到“人迎星”的发光点，点一下就完成观察。', '身体文化地图上，人迎是头面与颈部的一枚星光路牌。它属于足阳明胃经。', '只看3D铜人和文化图卡，不做身体操作；有问题请告诉老师或家长。', 'GB/T 12346-2021《经穴名称与定位》', 'https://openstd.samr.gov.cn/bzgk/std/newGbInfo?hcno=397548AE7248D3D87DD15E0AB8107185', -2.9677980068645167, 54.20000000000016, -2.3000000000000025, 40, 1) ON DUPLICATE KEY UPDATE `point_number`=VALUES(`point_number`), `name`=VALUES(`name`), `pinyin`=VALUES(`pinyin`), `meridian_code`=VALUES(`meridian_code`), `meridian_name`=VALUES(`meridian_name`), `meridian_english`=VALUES(`meridian_english`), `model_id`=VALUES(`model_id`), `body_area`=VALUES(`body_area`), `standard_location`=VALUES(`standard_location`), `child_location`=VALUES(`child_location`), `child_description`=VALUES(`child_description`), `safety_tip`=VALUES(`safety_tip`), `source_name`=VALUES(`source_name`), `source_link`=VALUES(`source_link`), `position_x`=VALUES(`position_x`), `position_y`=VALUES(`position_y`), `position_z`=VALUES(`position_z`), `sort_order`=VALUES(`sort_order`), `enabled`=VALUES(`enabled`);
INSERT INTO `acupoint_knowledge` (`code`, `point_number`, `name`, `pinyin`, `meridian_code`, `meridian_name`, `meridian_english`, `model_id`, `body_area`, `standard_location`, `child_location`, `child_description`, `safety_tip`, `source_name`, `source_link`, `position_x`, `position_y`, `position_z`, `sort_order`, `enabled`) VALUES ('ST-10', 10, '水突', 'Shuitu', 'ST', '足阳明胃经', 'Stomach Meridian', 'e10', '头面与颈部', '在颈前部，横平环状软骨，胸锁乳突肌前缘。', '转动3D小铜人，看向颈前部。在头面与颈部找到“水突星”的发光点，点一下就完成观察。', '水突的档案有两个关键词：头面与颈部和足阳明胃经。把它们连起来，线索就完整了。', '只看3D铜人和文化图卡，不做身体操作；有问题请告诉老师或家长。', 'GB/T 12346-2021《经穴名称与定位》', 'https://openstd.samr.gov.cn/bzgk/std/newGbInfo?hcno=397548AE7248D3D87DD15E0AB8107185', -2.267798006864516, 51.40000000000012, -2.2000000000000024, 41, 1) ON DUPLICATE KEY UPDATE `point_number`=VALUES(`point_number`), `name`=VALUES(`name`), `pinyin`=VALUES(`pinyin`), `meridian_code`=VALUES(`meridian_code`), `meridian_name`=VALUES(`meridian_name`), `meridian_english`=VALUES(`meridian_english`), `model_id`=VALUES(`model_id`), `body_area`=VALUES(`body_area`), `standard_location`=VALUES(`standard_location`), `child_location`=VALUES(`child_location`), `child_description`=VALUES(`child_description`), `safety_tip`=VALUES(`safety_tip`), `source_name`=VALUES(`source_name`), `source_link`=VALUES(`source_link`), `position_x`=VALUES(`position_x`), `position_y`=VALUES(`position_y`), `position_z`=VALUES(`position_z`), `sort_order`=VALUES(`sort_order`), `enabled`=VALUES(`enabled`);
INSERT INTO `acupoint_knowledge` (`code`, `point_number`, `name`, `pinyin`, `meridian_code`, `meridian_name`, `meridian_english`, `model_id`, `body_area`, `standard_location`, `child_location`, `child_description`, `safety_tip`, `source_name`, `source_link`, `position_x`, `position_y`, `position_z`, `sort_order`, `enabled`) VALUES ('ST-11', 11, '气舍', 'Qishe', 'ST', '足阳明胃经', 'Stomach Meridian', 'e11', '头面与颈部', '在颈前部，锁骨上小窝，锁骨胸骨端上缘，胸锁乳突肌胸骨头与锁骨头中间的凹陷中。', '转动3D小铜人，看向颈前部。在头面与颈部找到“气舍星”的发光点，点一下就完成观察。', '点亮气舍后，头面与颈部的地图多了一颗星。它是足阳明胃经路线的一站。', '只看3D铜人和文化图卡，不做身体操作；有问题请告诉老师或家长。', 'GB/T 12346-2021《经穴名称与定位》', 'https://openstd.samr.gov.cn/bzgk/std/newGbInfo?hcno=397548AE7248D3D87DD15E0AB8107185', -2.9677980068645167, 47.600000000000065, -1.2000000000000015, 42, 1) ON DUPLICATE KEY UPDATE `point_number`=VALUES(`point_number`), `name`=VALUES(`name`), `pinyin`=VALUES(`pinyin`), `meridian_code`=VALUES(`meridian_code`), `meridian_name`=VALUES(`meridian_name`), `meridian_english`=VALUES(`meridian_english`), `model_id`=VALUES(`model_id`), `body_area`=VALUES(`body_area`), `standard_location`=VALUES(`standard_location`), `child_location`=VALUES(`child_location`), `child_description`=VALUES(`child_description`), `safety_tip`=VALUES(`safety_tip`), `source_name`=VALUES(`source_name`), `source_link`=VALUES(`source_link`), `position_x`=VALUES(`position_x`), `position_y`=VALUES(`position_y`), `position_z`=VALUES(`position_z`), `sort_order`=VALUES(`sort_order`), `enabled`=VALUES(`enabled`);
INSERT INTO `acupoint_knowledge` (`code`, `point_number`, `name`, `pinyin`, `meridian_code`, `meridian_name`, `meridian_english`, `model_id`, `body_area`, `standard_location`, `child_location`, `child_description`, `safety_tip`, `source_name`, `source_link`, `position_x`, `position_y`, `position_z`, `sort_order`, `enabled`) VALUES ('ST-12', 12, '缺盆', 'Quepen', 'ST', '足阳明胃经', 'Stomach Meridian', 'e12', '头面与颈部', '在颈前部，锁骨上大窝，锁骨上缘凹陷中，前正中线旁开4寸。', '转动3D小铜人，看向颈前部。在头面与颈部找到“缺盆星”的发光点，点一下就完成观察。', '今天的探案印章叫缺盆。它不是按钮，而是帮我们读懂足阳明胃经的文化标记。', '只看3D铜人和文化图卡，不做身体操作；有问题请告诉老师或家长。', 'GB/T 12346-2021《经穴名称与定位》', 'https://openstd.samr.gov.cn/bzgk/std/newGbInfo?hcno=397548AE7248D3D87DD15E0AB8107185', -6.667798006864508, 48.60000000000008, -2.2000000000000024, 43, 1) ON DUPLICATE KEY UPDATE `point_number`=VALUES(`point_number`), `name`=VALUES(`name`), `pinyin`=VALUES(`pinyin`), `meridian_code`=VALUES(`meridian_code`), `meridian_name`=VALUES(`meridian_name`), `meridian_english`=VALUES(`meridian_english`), `model_id`=VALUES(`model_id`), `body_area`=VALUES(`body_area`), `standard_location`=VALUES(`standard_location`), `child_location`=VALUES(`child_location`), `child_description`=VALUES(`child_description`), `safety_tip`=VALUES(`safety_tip`), `source_name`=VALUES(`source_name`), `source_link`=VALUES(`source_link`), `position_x`=VALUES(`position_x`), `position_y`=VALUES(`position_y`), `position_z`=VALUES(`position_z`), `sort_order`=VALUES(`sort_order`), `enabled`=VALUES(`enabled`);
INSERT INTO `acupoint_knowledge` (`code`, `point_number`, `name`, `pinyin`, `meridian_code`, `meridian_name`, `meridian_english`, `model_id`, `body_area`, `standard_location`, `child_location`, `child_description`, `safety_tip`, `source_name`, `source_link`, `position_x`, `position_y`, `position_z`, `sort_order`, `enabled`) VALUES ('ST-13', 13, '气户', 'Qihu', 'ST', '足阳明胃经', 'Stomach Meridian', 'e13', '胸部', '在前胸部，锁骨下缘，前正中线旁开4寸。', '转动3D小铜人，看向前胸部。在胸部找到“气户星”的发光点，点一下就完成观察。', '小铜人把气户标成ST-13。这枚星光路牌帮我们记住胸部和足阳明胃经。', '只看3D铜人和文化图卡，不做身体操作；有问题请告诉老师或家长。', 'GB/T 12346-2021《经穴名称与定位》', 'https://openstd.samr.gov.cn/bzgk/std/newGbInfo?hcno=397548AE7248D3D87DD15E0AB8107185', -7.067798006864507, 47.600000000000065, -1.0000000000000013, 44, 1) ON DUPLICATE KEY UPDATE `point_number`=VALUES(`point_number`), `name`=VALUES(`name`), `pinyin`=VALUES(`pinyin`), `meridian_code`=VALUES(`meridian_code`), `meridian_name`=VALUES(`meridian_name`), `meridian_english`=VALUES(`meridian_english`), `model_id`=VALUES(`model_id`), `body_area`=VALUES(`body_area`), `standard_location`=VALUES(`standard_location`), `child_location`=VALUES(`child_location`), `child_description`=VALUES(`child_description`), `safety_tip`=VALUES(`safety_tip`), `source_name`=VALUES(`source_name`), `source_link`=VALUES(`source_link`), `position_x`=VALUES(`position_x`), `position_y`=VALUES(`position_y`), `position_z`=VALUES(`position_z`), `sort_order`=VALUES(`sort_order`), `enabled`=VALUES(`enabled`);
INSERT INTO `acupoint_knowledge` (`code`, `point_number`, `name`, `pinyin`, `meridian_code`, `meridian_name`, `meridian_english`, `model_id`, `body_area`, `standard_location`, `child_location`, `child_description`, `safety_tip`, `source_name`, `source_link`, `position_x`, `position_y`, `position_z`, `sort_order`, `enabled`) VALUES ('ST-14', 14, '库房', 'Kufang', 'ST', '足阳明胃经', 'Stomach Meridian', 'e14', '胸部', '在前胸部，第1肋间隙，前正中线旁开4寸。', '转动3D小铜人，看向前胸部。在胸部找到“库房星”的发光点，点一下就完成观察。', '今天的经络小旗叫库房。它不是按钮，而是帮我们读懂足阳明胃经的文化标记。', '只看3D铜人和文化图卡，不做身体操作；有问题请告诉老师或家长。', 'GB/T 12346-2021《经穴名称与定位》', 'https://openstd.samr.gov.cn/bzgk/std/newGbInfo?hcno=397548AE7248D3D87DD15E0AB8107185', -7.667798006864505, 44.800000000000026, 0.8999999999999986, 45, 1) ON DUPLICATE KEY UPDATE `point_number`=VALUES(`point_number`), `name`=VALUES(`name`), `pinyin`=VALUES(`pinyin`), `meridian_code`=VALUES(`meridian_code`), `meridian_name`=VALUES(`meridian_name`), `meridian_english`=VALUES(`meridian_english`), `model_id`=VALUES(`model_id`), `body_area`=VALUES(`body_area`), `standard_location`=VALUES(`standard_location`), `child_location`=VALUES(`child_location`), `child_description`=VALUES(`child_description`), `safety_tip`=VALUES(`safety_tip`), `source_name`=VALUES(`source_name`), `source_link`=VALUES(`source_link`), `position_x`=VALUES(`position_x`), `position_y`=VALUES(`position_y`), `position_z`=VALUES(`position_z`), `sort_order`=VALUES(`sort_order`), `enabled`=VALUES(`enabled`);
INSERT INTO `acupoint_knowledge` (`code`, `point_number`, `name`, `pinyin`, `meridian_code`, `meridian_name`, `meridian_english`, `model_id`, `body_area`, `standard_location`, `child_location`, `child_description`, `safety_tip`, `source_name`, `source_link`, `position_x`, `position_y`, `position_z`, `sort_order`, `enabled`) VALUES ('ST-15', 15, '屋翳', 'Wuyi', 'ST', '足阳明胃经', 'Stomach Meridian', 'e15', '胸部', '在前胸部，第2肋间隙，前正中线旁开4寸。注：可先确定胸骨角水平第2肋。', '转动3D小铜人，看向前胸部。在胸部找到“屋翳星”的发光点，点一下就完成观察。', '屋翳的档案有两个关键词：胸部和足阳明胃经。把它们连起来，线索就完整了。', '只看3D铜人和文化图卡，不做身体操作；有问题请告诉老师或家长。', 'GB/T 12346-2021《经穴名称与定位》', 'https://openstd.samr.gov.cn/bzgk/std/newGbInfo?hcno=397548AE7248D3D87DD15E0AB8107185', -8.767798006864501, 42.29999999999999, 2.3999999999999995, 46, 1) ON DUPLICATE KEY UPDATE `point_number`=VALUES(`point_number`), `name`=VALUES(`name`), `pinyin`=VALUES(`pinyin`), `meridian_code`=VALUES(`meridian_code`), `meridian_name`=VALUES(`meridian_name`), `meridian_english`=VALUES(`meridian_english`), `model_id`=VALUES(`model_id`), `body_area`=VALUES(`body_area`), `standard_location`=VALUES(`standard_location`), `child_location`=VALUES(`child_location`), `child_description`=VALUES(`child_description`), `safety_tip`=VALUES(`safety_tip`), `source_name`=VALUES(`source_name`), `source_link`=VALUES(`source_link`), `position_x`=VALUES(`position_x`), `position_y`=VALUES(`position_y`), `position_z`=VALUES(`position_z`), `sort_order`=VALUES(`sort_order`), `enabled`=VALUES(`enabled`);
INSERT INTO `acupoint_knowledge` (`code`, `point_number`, `name`, `pinyin`, `meridian_code`, `meridian_name`, `meridian_english`, `model_id`, `body_area`, `standard_location`, `child_location`, `child_description`, `safety_tip`, `source_name`, `source_link`, `position_x`, `position_y`, `position_z`, `sort_order`, `enabled`) VALUES ('ST-16', 16, '膺窗', 'Yingchuang', 'ST', '足阳明胃经', 'Stomach Meridian', 'e16', '胸部', '在前胸部，第3肋间隙，前正中线旁开4寸。', '转动3D小铜人，看向前胸部。在胸部找到“膺窗星”的发光点，点一下就完成观察。', 'ST-16是膺窗的星点编号。记住编号和足阳明胃经，就找到了它的文化档案。', '只看3D铜人和文化图卡，不做身体操作；有问题请告诉老师或家长。', 'GB/T 12346-2021《经穴名称与定位》', 'https://openstd.samr.gov.cn/bzgk/std/newGbInfo?hcno=397548AE7248D3D87DD15E0AB8107185', -9.867798006864497, 38.89999999999994, 4.2, 47, 1) ON DUPLICATE KEY UPDATE `point_number`=VALUES(`point_number`), `name`=VALUES(`name`), `pinyin`=VALUES(`pinyin`), `meridian_code`=VALUES(`meridian_code`), `meridian_name`=VALUES(`meridian_name`), `meridian_english`=VALUES(`meridian_english`), `model_id`=VALUES(`model_id`), `body_area`=VALUES(`body_area`), `standard_location`=VALUES(`standard_location`), `child_location`=VALUES(`child_location`), `child_description`=VALUES(`child_description`), `safety_tip`=VALUES(`safety_tip`), `source_name`=VALUES(`source_name`), `source_link`=VALUES(`source_link`), `position_x`=VALUES(`position_x`), `position_y`=VALUES(`position_y`), `position_z`=VALUES(`position_z`), `sort_order`=VALUES(`sort_order`), `enabled`=VALUES(`enabled`);
INSERT INTO `acupoint_knowledge` (`code`, `point_number`, `name`, `pinyin`, `meridian_code`, `meridian_name`, `meridian_english`, `model_id`, `body_area`, `standard_location`, `child_location`, `child_description`, `safety_tip`, `source_name`, `source_link`, `position_x`, `position_y`, `position_z`, `sort_order`, `enabled`) VALUES ('ST-17', 17, '乳中', 'Ruzhong', 'ST', '足阳明胃经', 'Stomach Meridian', 'e17', '胸部', '在前胸部，乳头中央。注：此穴现一般不针灸，用作取穴的体表标志。', '转动3D小铜人，看向前胸部。在胸部找到“乳中星”的发光点，点一下就完成观察。', '乳中是足阳明胃经的文化车站。它告诉我们：这条文化路线会经过胸部。', '只看3D铜人和文化图卡，不做身体操作；有问题请告诉老师或家长。', 'GB/T 12346-2021《经穴名称与定位》', 'https://openstd.samr.gov.cn/bzgk/std/newGbInfo?hcno=397548AE7248D3D87DD15E0AB8107185', -12.06779800686449, 33.19999999999986, 4.999999999999997, 48, 1) ON DUPLICATE KEY UPDATE `point_number`=VALUES(`point_number`), `name`=VALUES(`name`), `pinyin`=VALUES(`pinyin`), `meridian_code`=VALUES(`meridian_code`), `meridian_name`=VALUES(`meridian_name`), `meridian_english`=VALUES(`meridian_english`), `model_id`=VALUES(`model_id`), `body_area`=VALUES(`body_area`), `standard_location`=VALUES(`standard_location`), `child_location`=VALUES(`child_location`), `child_description`=VALUES(`child_description`), `safety_tip`=VALUES(`safety_tip`), `source_name`=VALUES(`source_name`), `source_link`=VALUES(`source_link`), `position_x`=VALUES(`position_x`), `position_y`=VALUES(`position_y`), `position_z`=VALUES(`position_z`), `sort_order`=VALUES(`sort_order`), `enabled`=VALUES(`enabled`);
INSERT INTO `acupoint_knowledge` (`code`, `point_number`, `name`, `pinyin`, `meridian_code`, `meridian_name`, `meridian_english`, `model_id`, `body_area`, `standard_location`, `child_location`, `child_description`, `safety_tip`, `source_name`, `source_link`, `position_x`, `position_y`, `position_z`, `sort_order`, `enabled`) VALUES ('ST-18', 18, '乳根', 'Rugen', 'ST', '足阳明胃经', 'Stomach Meridian', 'e18', '胸部', '在前胸部，第5肋间隙，前正中线旁开4寸。注：男性在乳头下1肋，女性在乳房根部弧线中点处。', '转动3D小铜人，看向前胸部。在胸部找到“乳根星”的发光点，点一下就完成观察。', '乳根对小侦探说：“请把我放进足阳明胃经档案。我的地图标签是胸部。”', '只看3D铜人和文化图卡，不做身体操作；有问题请告诉老师或家长。', 'GB/T 12346-2021《经穴名称与定位》', 'https://openstd.samr.gov.cn/bzgk/std/newGbInfo?hcno=397548AE7248D3D87DD15E0AB8107185', -12.06779800686449, 30.199999999999818, 2.1999999999999993, 49, 1) ON DUPLICATE KEY UPDATE `point_number`=VALUES(`point_number`), `name`=VALUES(`name`), `pinyin`=VALUES(`pinyin`), `meridian_code`=VALUES(`meridian_code`), `meridian_name`=VALUES(`meridian_name`), `meridian_english`=VALUES(`meridian_english`), `model_id`=VALUES(`model_id`), `body_area`=VALUES(`body_area`), `standard_location`=VALUES(`standard_location`), `child_location`=VALUES(`child_location`), `child_description`=VALUES(`child_description`), `safety_tip`=VALUES(`safety_tip`), `source_name`=VALUES(`source_name`), `source_link`=VALUES(`source_link`), `position_x`=VALUES(`position_x`), `position_y`=VALUES(`position_y`), `position_z`=VALUES(`position_z`), `sort_order`=VALUES(`sort_order`), `enabled`=VALUES(`enabled`);
INSERT INTO `acupoint_knowledge` (`code`, `point_number`, `name`, `pinyin`, `meridian_code`, `meridian_name`, `meridian_english`, `model_id`, `body_area`, `standard_location`, `child_location`, `child_description`, `safety_tip`, `source_name`, `source_link`, `position_x`, `position_y`, `position_z`, `sort_order`, `enabled`) VALUES ('ST-19', 19, '不容', 'Burong', 'ST', '足阳明胃经', 'Stomach Meridian', 'e19', '腹部', '在上腹部，脐中上6寸，前正中线旁开2寸。注：巨阙（CV14）旁开2寸。', '转动3D小铜人，看向腹部正面。在腹部找到“不容星”的发光点，点一下就完成观察。', '不容是足阳明胃经的探案印章。它告诉我们：这条文化路线会经过腹部。', '只看3D铜人和文化图卡，不做身体操作；有问题请告诉老师或家长。', 'GB/T 12346-2021《经穴名称与定位》', 'https://openstd.samr.gov.cn/bzgk/std/newGbInfo?hcno=397548AE7248D3D87DD15E0AB8107185', -3.167798006864517, 25.699999999999754, 6.599999999999992, 50, 1) ON DUPLICATE KEY UPDATE `point_number`=VALUES(`point_number`), `name`=VALUES(`name`), `pinyin`=VALUES(`pinyin`), `meridian_code`=VALUES(`meridian_code`), `meridian_name`=VALUES(`meridian_name`), `meridian_english`=VALUES(`meridian_english`), `model_id`=VALUES(`model_id`), `body_area`=VALUES(`body_area`), `standard_location`=VALUES(`standard_location`), `child_location`=VALUES(`child_location`), `child_description`=VALUES(`child_description`), `safety_tip`=VALUES(`safety_tip`), `source_name`=VALUES(`source_name`), `source_link`=VALUES(`source_link`), `position_x`=VALUES(`position_x`), `position_y`=VALUES(`position_y`), `position_z`=VALUES(`position_z`), `sort_order`=VALUES(`sort_order`), `enabled`=VALUES(`enabled`);
INSERT INTO `acupoint_knowledge` (`code`, `point_number`, `name`, `pinyin`, `meridian_code`, `meridian_name`, `meridian_english`, `model_id`, `body_area`, `standard_location`, `child_location`, `child_description`, `safety_tip`, `source_name`, `source_link`, `position_x`, `position_y`, `position_z`, `sort_order`, `enabled`) VALUES ('ST-20', 20, '承满', 'Chengman', 'ST', '足阳明胃经', 'Stomach Meridian', 'e20', '腹部', '在上腹部，脐中上5寸，前正中线旁开2寸。注：上脘（CV13）旁开2寸。', '转动3D小铜人，看向腹部正面。在腹部找到“承满星”的发光点，点一下就完成观察。', '承满带着一张“足阳明胃经”路线卡。把它收进档案，再认一认腹部。', '只看3D铜人和文化图卡，不做身体操作；有问题请告诉老师或家长。', 'GB/T 12346-2021《经穴名称与定位》', 'https://openstd.samr.gov.cn/bzgk/std/newGbInfo?hcno=397548AE7248D3D87DD15E0AB8107185', -3.167798006864517, 22.64727272727248, 6.699999999999991, 51, 1) ON DUPLICATE KEY UPDATE `point_number`=VALUES(`point_number`), `name`=VALUES(`name`), `pinyin`=VALUES(`pinyin`), `meridian_code`=VALUES(`meridian_code`), `meridian_name`=VALUES(`meridian_name`), `meridian_english`=VALUES(`meridian_english`), `model_id`=VALUES(`model_id`), `body_area`=VALUES(`body_area`), `standard_location`=VALUES(`standard_location`), `child_location`=VALUES(`child_location`), `child_description`=VALUES(`child_description`), `safety_tip`=VALUES(`safety_tip`), `source_name`=VALUES(`source_name`), `source_link`=VALUES(`source_link`), `position_x`=VALUES(`position_x`), `position_y`=VALUES(`position_y`), `position_z`=VALUES(`position_z`), `sort_order`=VALUES(`sort_order`), `enabled`=VALUES(`enabled`);
INSERT INTO `acupoint_knowledge` (`code`, `point_number`, `name`, `pinyin`, `meridian_code`, `meridian_name`, `meridian_english`, `model_id`, `body_area`, `standard_location`, `child_location`, `child_description`, `safety_tip`, `source_name`, `source_link`, `position_x`, `position_y`, `position_z`, `sort_order`, `enabled`) VALUES ('ST-21', 21, '梁门', 'Liangmen', 'ST', '足阳明胃经', 'Stomach Meridian', 'e21', '腹部', '在上腹部，脐中上4寸，前正中线旁开2寸。注：中脘（CV12）旁开2寸。', '转动3D小铜人，看向腹部正面。在腹部找到“梁门星”的发光点，点一下就完成观察。', '梁门带着一张“足阳明胃经”路线卡。把它收进档案，再认一认腹部。', '只看3D铜人和文化图卡，不做身体操作；有问题请告诉老师或家长。', 'GB/T 12346-2021《经穴名称与定位》', 'https://openstd.samr.gov.cn/bzgk/std/newGbInfo?hcno=397548AE7248D3D87DD15E0AB8107185', -3.167798006864517, 19.59454545454521, 6.699999999999991, 52, 1) ON DUPLICATE KEY UPDATE `point_number`=VALUES(`point_number`), `name`=VALUES(`name`), `pinyin`=VALUES(`pinyin`), `meridian_code`=VALUES(`meridian_code`), `meridian_name`=VALUES(`meridian_name`), `meridian_english`=VALUES(`meridian_english`), `model_id`=VALUES(`model_id`), `body_area`=VALUES(`body_area`), `standard_location`=VALUES(`standard_location`), `child_location`=VALUES(`child_location`), `child_description`=VALUES(`child_description`), `safety_tip`=VALUES(`safety_tip`), `source_name`=VALUES(`source_name`), `source_link`=VALUES(`source_link`), `position_x`=VALUES(`position_x`), `position_y`=VALUES(`position_y`), `position_z`=VALUES(`position_z`), `sort_order`=VALUES(`sort_order`), `enabled`=VALUES(`enabled`);
INSERT INTO `acupoint_knowledge` (`code`, `point_number`, `name`, `pinyin`, `meridian_code`, `meridian_name`, `meridian_english`, `model_id`, `body_area`, `standard_location`, `child_location`, `child_description`, `safety_tip`, `source_name`, `source_link`, `position_x`, `position_y`, `position_z`, `sort_order`, `enabled`) VALUES ('ST-22', 22, '关门', 'Guanmen', 'ST', '足阳明胃经', 'Stomach Meridian', 'e22', '腹部', '在上腹部，脐中上3寸，前正中线旁开2寸。注：横平建里（CV11）。', '转动3D小铜人，看向腹部正面。在腹部找到“关门星”的发光点，点一下就完成观察。', '身体文化地图上，关门是腹部的一枚探案印章。它属于足阳明胃经。', '只看3D铜人和文化图卡，不做身体操作；有问题请告诉老师或家长。', 'GB/T 12346-2021《经穴名称与定位》', 'https://openstd.samr.gov.cn/bzgk/std/newGbInfo?hcno=397548AE7248D3D87DD15E0AB8107185', -3.167798006864517, 16.541818181817938, 6.499999999999992, 53, 1) ON DUPLICATE KEY UPDATE `point_number`=VALUES(`point_number`), `name`=VALUES(`name`), `pinyin`=VALUES(`pinyin`), `meridian_code`=VALUES(`meridian_code`), `meridian_name`=VALUES(`meridian_name`), `meridian_english`=VALUES(`meridian_english`), `model_id`=VALUES(`model_id`), `body_area`=VALUES(`body_area`), `standard_location`=VALUES(`standard_location`), `child_location`=VALUES(`child_location`), `child_description`=VALUES(`child_description`), `safety_tip`=VALUES(`safety_tip`), `source_name`=VALUES(`source_name`), `source_link`=VALUES(`source_link`), `position_x`=VALUES(`position_x`), `position_y`=VALUES(`position_y`), `position_z`=VALUES(`position_z`), `sort_order`=VALUES(`sort_order`), `enabled`=VALUES(`enabled`);
INSERT INTO `acupoint_knowledge` (`code`, `point_number`, `name`, `pinyin`, `meridian_code`, `meridian_name`, `meridian_english`, `model_id`, `body_area`, `standard_location`, `child_location`, `child_description`, `safety_tip`, `source_name`, `source_link`, `position_x`, `position_y`, `position_z`, `sort_order`, `enabled`) VALUES ('ST-23', 23, '太乙', 'Taiyi', 'ST', '足阳明胃经', 'Stomach Meridian', 'e23', '腹部', '在上腹部，脐中上2寸，前正中线旁开2寸。注：横平下脘（CV10）。', '转动3D小铜人，看向腹部正面。在腹部找到“太乙星”的发光点，点一下就完成观察。', '太乙是足阳明胃经的文化车站。它告诉我们：这条文化路线会经过腹部。', '只看3D铜人和文化图卡，不做身体操作；有问题请告诉老师或家长。', 'GB/T 12346-2021《经穴名称与定位》', 'https://openstd.samr.gov.cn/bzgk/std/newGbInfo?hcno=397548AE7248D3D87DD15E0AB8107185', -3.167798006864517, 13.489090909090663, 6.699999999999991, 54, 1) ON DUPLICATE KEY UPDATE `point_number`=VALUES(`point_number`), `name`=VALUES(`name`), `pinyin`=VALUES(`pinyin`), `meridian_code`=VALUES(`meridian_code`), `meridian_name`=VALUES(`meridian_name`), `meridian_english`=VALUES(`meridian_english`), `model_id`=VALUES(`model_id`), `body_area`=VALUES(`body_area`), `standard_location`=VALUES(`standard_location`), `child_location`=VALUES(`child_location`), `child_description`=VALUES(`child_description`), `safety_tip`=VALUES(`safety_tip`), `source_name`=VALUES(`source_name`), `source_link`=VALUES(`source_link`), `position_x`=VALUES(`position_x`), `position_y`=VALUES(`position_y`), `position_z`=VALUES(`position_z`), `sort_order`=VALUES(`sort_order`), `enabled`=VALUES(`enabled`);
INSERT INTO `acupoint_knowledge` (`code`, `point_number`, `name`, `pinyin`, `meridian_code`, `meridian_name`, `meridian_english`, `model_id`, `body_area`, `standard_location`, `child_location`, `child_description`, `safety_tip`, `source_name`, `source_link`, `position_x`, `position_y`, `position_z`, `sort_order`, `enabled`) VALUES ('ST-24', 24, '滑肉门', 'Huaroumen', 'ST', '足阳明胃经', 'Stomach Meridian', 'e24', '腹部', '在上腹部，脐中上1寸，前正中线旁开2寸。注：横平水分（CV9）。', '转动3D小铜人，看向腹部正面。在腹部找到“滑肉门星”的发光点，点一下就完成观察。', '跟着足阳明胃经路线，小侦探在腹部遇见了滑肉门。这是今天的文化新名字。', '只看3D铜人和文化图卡，不做身体操作；有问题请告诉老师或家长。', 'GB/T 12346-2021《经穴名称与定位》', 'https://openstd.samr.gov.cn/bzgk/std/newGbInfo?hcno=397548AE7248D3D87DD15E0AB8107185', -3.167798006864517, 10.43636363636339, 7.09999999999999, 55, 1) ON DUPLICATE KEY UPDATE `point_number`=VALUES(`point_number`), `name`=VALUES(`name`), `pinyin`=VALUES(`pinyin`), `meridian_code`=VALUES(`meridian_code`), `meridian_name`=VALUES(`meridian_name`), `meridian_english`=VALUES(`meridian_english`), `model_id`=VALUES(`model_id`), `body_area`=VALUES(`body_area`), `standard_location`=VALUES(`standard_location`), `child_location`=VALUES(`child_location`), `child_description`=VALUES(`child_description`), `safety_tip`=VALUES(`safety_tip`), `source_name`=VALUES(`source_name`), `source_link`=VALUES(`source_link`), `position_x`=VALUES(`position_x`), `position_y`=VALUES(`position_y`), `position_z`=VALUES(`position_z`), `sort_order`=VALUES(`sort_order`), `enabled`=VALUES(`enabled`);
INSERT INTO `acupoint_knowledge` (`code`, `point_number`, `name`, `pinyin`, `meridian_code`, `meridian_name`, `meridian_english`, `model_id`, `body_area`, `standard_location`, `child_location`, `child_description`, `safety_tip`, `source_name`, `source_link`, `position_x`, `position_y`, `position_z`, `sort_order`, `enabled`) VALUES ('ST-25', 25, '天枢', 'Tianshu', 'ST', '足阳明胃经', 'Stomach Meridian', 'e25', '腹部', '在上腹部，横平脐中，前正中线旁开2寸。', '转动3D小铜人，看向腹部正面。在腹部找到“天枢星”的发光点，点一下就完成观察。', '跟着足阳明胃经路线，小侦探在腹部遇见了天枢。这是今天的文化新名字。', '只看3D铜人和文化图卡，不做身体操作；有问题请告诉老师或家长。', 'GB/T 12346-2021《经穴名称与定位》', 'https://openstd.samr.gov.cn/bzgk/std/newGbInfo?hcno=397548AE7248D3D87DD15E0AB8107185', -3.167798006864517, 7.383636363636118, 6.99999999999999, 56, 1) ON DUPLICATE KEY UPDATE `point_number`=VALUES(`point_number`), `name`=VALUES(`name`), `pinyin`=VALUES(`pinyin`), `meridian_code`=VALUES(`meridian_code`), `meridian_name`=VALUES(`meridian_name`), `meridian_english`=VALUES(`meridian_english`), `model_id`=VALUES(`model_id`), `body_area`=VALUES(`body_area`), `standard_location`=VALUES(`standard_location`), `child_location`=VALUES(`child_location`), `child_description`=VALUES(`child_description`), `safety_tip`=VALUES(`safety_tip`), `source_name`=VALUES(`source_name`), `source_link`=VALUES(`source_link`), `position_x`=VALUES(`position_x`), `position_y`=VALUES(`position_y`), `position_z`=VALUES(`position_z`), `sort_order`=VALUES(`sort_order`), `enabled`=VALUES(`enabled`);
INSERT INTO `acupoint_knowledge` (`code`, `point_number`, `name`, `pinyin`, `meridian_code`, `meridian_name`, `meridian_english`, `model_id`, `body_area`, `standard_location`, `child_location`, `child_description`, `safety_tip`, `source_name`, `source_link`, `position_x`, `position_y`, `position_z`, `sort_order`, `enabled`) VALUES ('ST-26', 26, '外陵', 'Wailing', 'ST', '足阳明胃经', 'Stomach Meridian', 'e26', '腹部', '在下腹部，脐中下1寸，前正中线旁开2寸。注：横平阴交（CV7）。', '转动3D小铜人，看向腹部正面。在腹部找到“外陵星”的发光点，点一下就完成观察。', '今天的经络小旗叫外陵。它不是按钮，而是帮我们读懂足阳明胃经的文化标记。', '只看3D铜人和文化图卡，不做身体操作；有问题请告诉老师或家长。', 'GB/T 12346-2021《经穴名称与定位》', 'https://openstd.samr.gov.cn/bzgk/std/newGbInfo?hcno=397548AE7248D3D87DD15E0AB8107185', -3.167798006864517, 4.330909090908847, 6.899999999999991, 57, 1) ON DUPLICATE KEY UPDATE `point_number`=VALUES(`point_number`), `name`=VALUES(`name`), `pinyin`=VALUES(`pinyin`), `meridian_code`=VALUES(`meridian_code`), `meridian_name`=VALUES(`meridian_name`), `meridian_english`=VALUES(`meridian_english`), `model_id`=VALUES(`model_id`), `body_area`=VALUES(`body_area`), `standard_location`=VALUES(`standard_location`), `child_location`=VALUES(`child_location`), `child_description`=VALUES(`child_description`), `safety_tip`=VALUES(`safety_tip`), `source_name`=VALUES(`source_name`), `source_link`=VALUES(`source_link`), `position_x`=VALUES(`position_x`), `position_y`=VALUES(`position_y`), `position_z`=VALUES(`position_z`), `sort_order`=VALUES(`sort_order`), `enabled`=VALUES(`enabled`);
INSERT INTO `acupoint_knowledge` (`code`, `point_number`, `name`, `pinyin`, `meridian_code`, `meridian_name`, `meridian_english`, `model_id`, `body_area`, `standard_location`, `child_location`, `child_description`, `safety_tip`, `source_name`, `source_link`, `position_x`, `position_y`, `position_z`, `sort_order`, `enabled`) VALUES ('ST-27', 27, '大巨', 'Daju', 'ST', '足阳明胃经', 'Stomach Meridian', 'e27', '腹部', '在下腹部，脐中下2寸，前正中线旁开2寸。注：横平石门（CV5）。', '转动3D小铜人，看向腹部正面。在腹部找到“大巨星”的发光点，点一下就完成观察。', '大巨的档案有两个关键词：腹部和足阳明胃经。把它们连起来，线索就完整了。', '只看3D铜人和文化图卡，不做身体操作；有问题请告诉老师或家长。', 'GB/T 12346-2021《经穴名称与定位》', 'https://openstd.samr.gov.cn/bzgk/std/newGbInfo?hcno=397548AE7248D3D87DD15E0AB8107185', -3.167798006864517, 1.2781818181815723, 6.599999999999992, 58, 1) ON DUPLICATE KEY UPDATE `point_number`=VALUES(`point_number`), `name`=VALUES(`name`), `pinyin`=VALUES(`pinyin`), `meridian_code`=VALUES(`meridian_code`), `meridian_name`=VALUES(`meridian_name`), `meridian_english`=VALUES(`meridian_english`), `model_id`=VALUES(`model_id`), `body_area`=VALUES(`body_area`), `standard_location`=VALUES(`standard_location`), `child_location`=VALUES(`child_location`), `child_description`=VALUES(`child_description`), `safety_tip`=VALUES(`safety_tip`), `source_name`=VALUES(`source_name`), `source_link`=VALUES(`source_link`), `position_x`=VALUES(`position_x`), `position_y`=VALUES(`position_y`), `position_z`=VALUES(`position_z`), `sort_order`=VALUES(`sort_order`), `enabled`=VALUES(`enabled`);
INSERT INTO `acupoint_knowledge` (`code`, `point_number`, `name`, `pinyin`, `meridian_code`, `meridian_name`, `meridian_english`, `model_id`, `body_area`, `standard_location`, `child_location`, `child_description`, `safety_tip`, `source_name`, `source_link`, `position_x`, `position_y`, `position_z`, `sort_order`, `enabled`) VALUES ('ST-28', 28, '水道', 'Shuidao', 'ST', '足阳明胃经', 'Stomach Meridian', 'e28', '腹部', '在下腹部，脐中下3寸，前正中线旁开2寸。注：关元（CV4）旁开2寸。', '转动3D小铜人，看向腹部正面。在腹部找到“水道星”的发光点，点一下就完成观察。', '水道对小侦探说：“请把我放进足阳明胃经档案。我的地图标签是腹部。”', '只看3D铜人和文化图卡，不做身体操作；有问题请告诉老师或家长。', 'GB/T 12346-2021《经穴名称与定位》', 'https://openstd.samr.gov.cn/bzgk/std/newGbInfo?hcno=397548AE7248D3D87DD15E0AB8107185', -3.167798006864517, -1.7745454545457022, 6.299999999999993, 59, 1) ON DUPLICATE KEY UPDATE `point_number`=VALUES(`point_number`), `name`=VALUES(`name`), `pinyin`=VALUES(`pinyin`), `meridian_code`=VALUES(`meridian_code`), `meridian_name`=VALUES(`meridian_name`), `meridian_english`=VALUES(`meridian_english`), `model_id`=VALUES(`model_id`), `body_area`=VALUES(`body_area`), `standard_location`=VALUES(`standard_location`), `child_location`=VALUES(`child_location`), `child_description`=VALUES(`child_description`), `safety_tip`=VALUES(`safety_tip`), `source_name`=VALUES(`source_name`), `source_link`=VALUES(`source_link`), `position_x`=VALUES(`position_x`), `position_y`=VALUES(`position_y`), `position_z`=VALUES(`position_z`), `sort_order`=VALUES(`sort_order`), `enabled`=VALUES(`enabled`);
INSERT INTO `acupoint_knowledge` (`code`, `point_number`, `name`, `pinyin`, `meridian_code`, `meridian_name`, `meridian_english`, `model_id`, `body_area`, `standard_location`, `child_location`, `child_description`, `safety_tip`, `source_name`, `source_link`, `position_x`, `position_y`, `position_z`, `sort_order`, `enabled`) VALUES ('ST-29', 29, '归来 (归来)', 'Guilai', 'ST', '足阳明胃经', 'Stomach Meridian', 'e29', '腹部', '在下腹部，脐中下4寸，前正中线旁开2寸。注：中极（CV3）旁开2寸。', '转动3D小铜人，看向腹部正面。在腹部找到“归来 (归来)星”的发光点，点一下就完成观察。', '跟着足阳明胃经路线，小侦探在腹部遇见了归来 (归来)。这是今天的文化新名字。', '只看3D铜人和文化图卡，不做身体操作；有问题请告诉老师或家长。', 'GB/T 12346-2021《经穴名称与定位》', 'https://openstd.samr.gov.cn/bzgk/std/newGbInfo?hcno=397548AE7248D3D87DD15E0AB8107185', -3.167798006864517, -4.827272727272973, 5.699999999999995, 60, 1) ON DUPLICATE KEY UPDATE `point_number`=VALUES(`point_number`), `name`=VALUES(`name`), `pinyin`=VALUES(`pinyin`), `meridian_code`=VALUES(`meridian_code`), `meridian_name`=VALUES(`meridian_name`), `meridian_english`=VALUES(`meridian_english`), `model_id`=VALUES(`model_id`), `body_area`=VALUES(`body_area`), `standard_location`=VALUES(`standard_location`), `child_location`=VALUES(`child_location`), `child_description`=VALUES(`child_description`), `safety_tip`=VALUES(`safety_tip`), `source_name`=VALUES(`source_name`), `source_link`=VALUES(`source_link`), `position_x`=VALUES(`position_x`), `position_y`=VALUES(`position_y`), `position_z`=VALUES(`position_z`), `sort_order`=VALUES(`sort_order`), `enabled`=VALUES(`enabled`);
INSERT INTO `acupoint_knowledge` (`code`, `point_number`, `name`, `pinyin`, `meridian_code`, `meridian_name`, `meridian_english`, `model_id`, `body_area`, `standard_location`, `child_location`, `child_description`, `safety_tip`, `source_name`, `source_link`, `position_x`, `position_y`, `position_z`, `sort_order`, `enabled`) VALUES ('ST-30', 30, '气冲', 'Qichong', 'ST', '足阳明胃经', 'Stomach Meridian', 'e30', '腹部', '在腹股沟，耻骨联合上缘，前正中线旁开2寸，动脉搏动处。注：曲骨（CV2）旁开2寸。', '转动3D小铜人，看向腹部正面。在腹部找到“气冲星”的发光点，点一下就完成观察。', '气冲对小侦探说：“请把我放进足阳明胃经档案。我的地图标签是腹部。”', '只看3D铜人和文化图卡，不做身体操作；有问题请告诉老师或家长。', 'GB/T 12346-2021《经穴名称与定位》', 'https://openstd.samr.gov.cn/bzgk/std/newGbInfo?hcno=397548AE7248D3D87DD15E0AB8107185', -3.167798006864517, -7.880000000000244, 4.599999999999999, 61, 1) ON DUPLICATE KEY UPDATE `point_number`=VALUES(`point_number`), `name`=VALUES(`name`), `pinyin`=VALUES(`pinyin`), `meridian_code`=VALUES(`meridian_code`), `meridian_name`=VALUES(`meridian_name`), `meridian_english`=VALUES(`meridian_english`), `model_id`=VALUES(`model_id`), `body_area`=VALUES(`body_area`), `standard_location`=VALUES(`standard_location`), `child_location`=VALUES(`child_location`), `child_description`=VALUES(`child_description`), `safety_tip`=VALUES(`safety_tip`), `source_name`=VALUES(`source_name`), `source_link`=VALUES(`source_link`), `position_x`=VALUES(`position_x`), `position_y`=VALUES(`position_y`), `position_z`=VALUES(`position_z`), `sort_order`=VALUES(`sort_order`), `enabled`=VALUES(`enabled`);
INSERT INTO `acupoint_knowledge` (`code`, `point_number`, `name`, `pinyin`, `meridian_code`, `meridian_name`, `meridian_english`, `model_id`, `body_area`, `standard_location`, `child_location`, `child_description`, `safety_tip`, `source_name`, `source_link`, `position_x`, `position_y`, `position_z`, `sort_order`, `enabled`) VALUES ('ST-31', 31, '髀关', 'Biguan', 'ST', '足阳明胃经', 'Stomach Meridian', 'e31', '髋腿部', '在股前侧，股直肌近端、缝匠肌与阔筋膜张肌3条肌肉之间凹陷中。', '转动3D小铜人，看向下肢前外侧。在髋腿部找到“髀关星”的发光点，点一下就完成观察。', '小铜人把髀关标成ST-31。这枚星光路牌帮我们记住髋腿部和足阳明胃经。', '只看3D铜人和文化图卡，不做身体操作；有问题请告诉老师或家长。', 'GB/T 12346-2021《经穴名称与定位》', 'https://openstd.samr.gov.cn/bzgk/std/newGbInfo?hcno=397548AE7248D3D87DD15E0AB8107185', -12.467798006864488, -11.280000000000232, 4.100000000000001, 62, 1) ON DUPLICATE KEY UPDATE `point_number`=VALUES(`point_number`), `name`=VALUES(`name`), `pinyin`=VALUES(`pinyin`), `meridian_code`=VALUES(`meridian_code`), `meridian_name`=VALUES(`meridian_name`), `meridian_english`=VALUES(`meridian_english`), `model_id`=VALUES(`model_id`), `body_area`=VALUES(`body_area`), `standard_location`=VALUES(`standard_location`), `child_location`=VALUES(`child_location`), `child_description`=VALUES(`child_description`), `safety_tip`=VALUES(`safety_tip`), `source_name`=VALUES(`source_name`), `source_link`=VALUES(`source_link`), `position_x`=VALUES(`position_x`), `position_y`=VALUES(`position_y`), `position_z`=VALUES(`position_z`), `sort_order`=VALUES(`sort_order`), `enabled`=VALUES(`enabled`);
INSERT INTO `acupoint_knowledge` (`code`, `point_number`, `name`, `pinyin`, `meridian_code`, `meridian_name`, `meridian_english`, `model_id`, `body_area`, `standard_location`, `child_location`, `child_description`, `safety_tip`, `source_name`, `source_link`, `position_x`, `position_y`, `position_z`, `sort_order`, `enabled`) VALUES ('ST-32', 32, '伏兔', 'Futu', 'ST', '足阳明胃经', 'Stomach Meridian', 'e32', '髋腿部', '在股前外侧，髌底上6寸，髂前上棘与髌底外侧端的连线上。', '转动3D小铜人，看向下肢前外侧。在髋腿部找到“伏兔星”的发光点，点一下就完成观察。', '在髋腿部的星点档案里，伏兔和足阳明胃经站在同一条路线上。', '只看3D铜人和文化图卡，不做身体操作；有问题请告诉老师或家长。', 'GB/T 12346-2021《经穴名称与定位》', 'https://openstd.samr.gov.cn/bzgk/std/newGbInfo?hcno=397548AE7248D3D87DD15E0AB8107185', -12.467798006864488, -28.48000000000039, 4.300000000000001, 63, 1) ON DUPLICATE KEY UPDATE `point_number`=VALUES(`point_number`), `name`=VALUES(`name`), `pinyin`=VALUES(`pinyin`), `meridian_code`=VALUES(`meridian_code`), `meridian_name`=VALUES(`meridian_name`), `meridian_english`=VALUES(`meridian_english`), `model_id`=VALUES(`model_id`), `body_area`=VALUES(`body_area`), `standard_location`=VALUES(`standard_location`), `child_location`=VALUES(`child_location`), `child_description`=VALUES(`child_description`), `safety_tip`=VALUES(`safety_tip`), `source_name`=VALUES(`source_name`), `source_link`=VALUES(`source_link`), `position_x`=VALUES(`position_x`), `position_y`=VALUES(`position_y`), `position_z`=VALUES(`position_z`), `sort_order`=VALUES(`sort_order`), `enabled`=VALUES(`enabled`);
INSERT INTO `acupoint_knowledge` (`code`, `point_number`, `name`, `pinyin`, `meridian_code`, `meridian_name`, `meridian_english`, `model_id`, `body_area`, `standard_location`, `child_location`, `child_description`, `safety_tip`, `source_name`, `source_link`, `position_x`, `position_y`, `position_z`, `sort_order`, `enabled`) VALUES ('ST-33', 33, '阴市', 'Yinshi', 'ST', '足阳明胃经', 'Stomach Meridian', 'e33', '髋腿部', '在股前外侧，髌底上3寸，股直肌肌腱外侧缘。注：伏兔与髌底外侧端连线中点。', '转动3D小铜人，看向下肢前外侧。在髋腿部找到“阴市星”的发光点，点一下就完成观察。', '阴市是足阳明胃经的经络小旗。它告诉我们：这条文化路线会经过髋腿部。', '只看3D铜人和文化图卡，不做身体操作；有问题请告诉老师或家长。', 'GB/T 12346-2021《经穴名称与定位》', 'https://openstd.samr.gov.cn/bzgk/std/newGbInfo?hcno=397548AE7248D3D87DD15E0AB8107185', -12.467798006864488, -36.2800000000005, 2.900000000000001, 64, 1) ON DUPLICATE KEY UPDATE `point_number`=VALUES(`point_number`), `name`=VALUES(`name`), `pinyin`=VALUES(`pinyin`), `meridian_code`=VALUES(`meridian_code`), `meridian_name`=VALUES(`meridian_name`), `meridian_english`=VALUES(`meridian_english`), `model_id`=VALUES(`model_id`), `body_area`=VALUES(`body_area`), `standard_location`=VALUES(`standard_location`), `child_location`=VALUES(`child_location`), `child_description`=VALUES(`child_description`), `safety_tip`=VALUES(`safety_tip`), `source_name`=VALUES(`source_name`), `source_link`=VALUES(`source_link`), `position_x`=VALUES(`position_x`), `position_y`=VALUES(`position_y`), `position_z`=VALUES(`position_z`), `sort_order`=VALUES(`sort_order`), `enabled`=VALUES(`enabled`);
INSERT INTO `acupoint_knowledge` (`code`, `point_number`, `name`, `pinyin`, `meridian_code`, `meridian_name`, `meridian_english`, `model_id`, `body_area`, `standard_location`, `child_location`, `child_description`, `safety_tip`, `source_name`, `source_link`, `position_x`, `position_y`, `position_z`, `sort_order`, `enabled`) VALUES ('ST-34', 34, '梁丘', 'Liangqiu', 'ST', '足阳明胃经', 'Stomach Meridian', 'e34', '髋腿部', '在股前外侧，髌底上2寸，股外侧肌与股直肌肌腱之间。注：阴市直下1寸处。', '转动3D小铜人，看向下肢前外侧。在髋腿部找到“梁丘星”的发光点，点一下就完成观察。', '跟着足阳明胃经路线，小侦探在髋腿部遇见了梁丘。这是今天的文化新名字。', '只看3D铜人和文化图卡，不做身体操作；有问题请告诉老师或家长。', 'GB/T 12346-2021《经穴名称与定位》', 'https://openstd.samr.gov.cn/bzgk/std/newGbInfo?hcno=397548AE7248D3D87DD15E0AB8107185', -12.467798006864488, -38.98000000000054, 2.3000000000000003, 65, 1) ON DUPLICATE KEY UPDATE `point_number`=VALUES(`point_number`), `name`=VALUES(`name`), `pinyin`=VALUES(`pinyin`), `meridian_code`=VALUES(`meridian_code`), `meridian_name`=VALUES(`meridian_name`), `meridian_english`=VALUES(`meridian_english`), `model_id`=VALUES(`model_id`), `body_area`=VALUES(`body_area`), `standard_location`=VALUES(`standard_location`), `child_location`=VALUES(`child_location`), `child_description`=VALUES(`child_description`), `safety_tip`=VALUES(`safety_tip`), `source_name`=VALUES(`source_name`), `source_link`=VALUES(`source_link`), `position_x`=VALUES(`position_x`), `position_y`=VALUES(`position_y`), `position_z`=VALUES(`position_z`), `sort_order`=VALUES(`sort_order`), `enabled`=VALUES(`enabled`);
INSERT INTO `acupoint_knowledge` (`code`, `point_number`, `name`, `pinyin`, `meridian_code`, `meridian_name`, `meridian_english`, `model_id`, `body_area`, `standard_location`, `child_location`, `child_description`, `safety_tip`, `source_name`, `source_link`, `position_x`, `position_y`, `position_z`, `sort_order`, `enabled`) VALUES ('ST-35', 35, '犊鼻', 'Dubi', 'ST', '足阳明胃经', 'Stomach Meridian', 'e35', '髋腿部', '在膝前侧，髌韧带外侧凹陷中。注：屈膝45°，髌骨外下方凹陷中。', '转动3D小铜人，看向下肢前外侧。在髋腿部找到“犊鼻星”的发光点，点一下就完成观察。', '小侦探找到了犊鼻。档案上写着“足阳明胃经”，它的地图区域是髋腿部。', '只看3D铜人和文化图卡，不做身体操作；有问题请告诉老师或家长。', 'GB/T 12346-2021《经穴名称与定位》', 'https://openstd.samr.gov.cn/bzgk/std/newGbInfo?hcno=397548AE7248D3D87DD15E0AB8107185', -12.467798006864488, -47.18000000000065, 1.4999999999999996, 66, 1) ON DUPLICATE KEY UPDATE `point_number`=VALUES(`point_number`), `name`=VALUES(`name`), `pinyin`=VALUES(`pinyin`), `meridian_code`=VALUES(`meridian_code`), `meridian_name`=VALUES(`meridian_name`), `meridian_english`=VALUES(`meridian_english`), `model_id`=VALUES(`model_id`), `body_area`=VALUES(`body_area`), `standard_location`=VALUES(`standard_location`), `child_location`=VALUES(`child_location`), `child_description`=VALUES(`child_description`), `safety_tip`=VALUES(`safety_tip`), `source_name`=VALUES(`source_name`), `source_link`=VALUES(`source_link`), `position_x`=VALUES(`position_x`), `position_y`=VALUES(`position_y`), `position_z`=VALUES(`position_z`), `sort_order`=VALUES(`sort_order`), `enabled`=VALUES(`enabled`);
INSERT INTO `acupoint_knowledge` (`code`, `point_number`, `name`, `pinyin`, `meridian_code`, `meridian_name`, `meridian_english`, `model_id`, `body_area`, `standard_location`, `child_location`, `child_description`, `safety_tip`, `source_name`, `source_link`, `position_x`, `position_y`, `position_z`, `sort_order`, `enabled`) VALUES ('ST-36', 36, '足三里', 'Zusanli', 'ST', '足阳明胃经', 'Stomach Meridian', 'e36', '髋腿部', '在小腿外侧，犊鼻（ST35）下3寸，犊鼻（ST35）与解溪（ST41）连线上。注：在胫骨前肌上取穴。', '转动3D小铜人，看向下肢前外侧。在髋腿部找到“足三里星”的发光点，点一下就完成观察。', '足三里对小侦探说：“请把我放进足阳明胃经档案。我的地图标签是髋腿部。”', '只看3D铜人和文化图卡，不做身体操作；有问题请告诉老师或家长。', 'GB/T 12346-2021《经穴名称与定位》', 'https://openstd.samr.gov.cn/bzgk/std/newGbInfo?hcno=397548AE7248D3D87DD15E0AB8107185', -12.467798006864488, -53.18000000000074, -0.10000000000000153, 67, 1) ON DUPLICATE KEY UPDATE `point_number`=VALUES(`point_number`), `name`=VALUES(`name`), `pinyin`=VALUES(`pinyin`), `meridian_code`=VALUES(`meridian_code`), `meridian_name`=VALUES(`meridian_name`), `meridian_english`=VALUES(`meridian_english`), `model_id`=VALUES(`model_id`), `body_area`=VALUES(`body_area`), `standard_location`=VALUES(`standard_location`), `child_location`=VALUES(`child_location`), `child_description`=VALUES(`child_description`), `safety_tip`=VALUES(`safety_tip`), `source_name`=VALUES(`source_name`), `source_link`=VALUES(`source_link`), `position_x`=VALUES(`position_x`), `position_y`=VALUES(`position_y`), `position_z`=VALUES(`position_z`), `sort_order`=VALUES(`sort_order`), `enabled`=VALUES(`enabled`);
INSERT INTO `acupoint_knowledge` (`code`, `point_number`, `name`, `pinyin`, `meridian_code`, `meridian_name`, `meridian_english`, `model_id`, `body_area`, `standard_location`, `child_location`, `child_description`, `safety_tip`, `source_name`, `source_link`, `position_x`, `position_y`, `position_z`, `sort_order`, `enabled`) VALUES ('ST-37', 37, '上巨虚', 'Shangjuxu', 'ST', '足阳明胃经', 'Stomach Meridian', 'e37', '髋腿部', '在小腿外侧，犊鼻（ST35）下6寸，犊鼻（ST35）与解溪（ST41）连线上。注：在胫骨前肌上取穴。', '转动3D小铜人，看向下肢前外侧。在髋腿部找到“上巨虚星”的发光点，点一下就完成观察。', '在髋腿部的星点档案里，上巨虚和足阳明胃经站在同一条路线上。', '只看3D铜人和文化图卡，不做身体操作；有问题请告诉老师或家长。', 'GB/T 12346-2021《经穴名称与定位》', 'https://openstd.samr.gov.cn/bzgk/std/newGbInfo?hcno=397548AE7248D3D87DD15E0AB8107185', -12.467798006864488, -63.68000000000089, -0.7000000000000015, 68, 1) ON DUPLICATE KEY UPDATE `point_number`=VALUES(`point_number`), `name`=VALUES(`name`), `pinyin`=VALUES(`pinyin`), `meridian_code`=VALUES(`meridian_code`), `meridian_name`=VALUES(`meridian_name`), `meridian_english`=VALUES(`meridian_english`), `model_id`=VALUES(`model_id`), `body_area`=VALUES(`body_area`), `standard_location`=VALUES(`standard_location`), `child_location`=VALUES(`child_location`), `child_description`=VALUES(`child_description`), `safety_tip`=VALUES(`safety_tip`), `source_name`=VALUES(`source_name`), `source_link`=VALUES(`source_link`), `position_x`=VALUES(`position_x`), `position_y`=VALUES(`position_y`), `position_z`=VALUES(`position_z`), `sort_order`=VALUES(`sort_order`), `enabled`=VALUES(`enabled`);
INSERT INTO `acupoint_knowledge` (`code`, `point_number`, `name`, `pinyin`, `meridian_code`, `meridian_name`, `meridian_english`, `model_id`, `body_area`, `standard_location`, `child_location`, `child_description`, `safety_tip`, `source_name`, `source_link`, `position_x`, `position_y`, `position_z`, `sort_order`, `enabled`) VALUES ('ST-38', 38, '条口', 'Tiaokou', 'ST', '足阳明胃经', 'Stomach Meridian', 'e38', '髋腿部', '在小腿外侧，犊鼻（ST35）下8寸，犊鼻（ST35）与解溪（ST41）连线上。注：横平丰隆（ST40）。', '转动3D小铜人，看向下肢前外侧。在髋腿部找到“条口星”的发光点，点一下就完成观察。', '今天的经络小旗叫条口。它不是按钮，而是帮我们读懂足阳明胃经的文化标记。', '只看3D铜人和文化图卡，不做身体操作；有问题请告诉老师或家长。', 'GB/T 12346-2021《经穴名称与定位》', 'https://openstd.samr.gov.cn/bzgk/std/newGbInfo?hcno=397548AE7248D3D87DD15E0AB8107185', -11.76779800686449, -69.78000000000057, -1.6000000000000019, 69, 1) ON DUPLICATE KEY UPDATE `point_number`=VALUES(`point_number`), `name`=VALUES(`name`), `pinyin`=VALUES(`pinyin`), `meridian_code`=VALUES(`meridian_code`), `meridian_name`=VALUES(`meridian_name`), `meridian_english`=VALUES(`meridian_english`), `model_id`=VALUES(`model_id`), `body_area`=VALUES(`body_area`), `standard_location`=VALUES(`standard_location`), `child_location`=VALUES(`child_location`), `child_description`=VALUES(`child_description`), `safety_tip`=VALUES(`safety_tip`), `source_name`=VALUES(`source_name`), `source_link`=VALUES(`source_link`), `position_x`=VALUES(`position_x`), `position_y`=VALUES(`position_y`), `position_z`=VALUES(`position_z`), `sort_order`=VALUES(`sort_order`), `enabled`=VALUES(`enabled`);
INSERT INTO `acupoint_knowledge` (`code`, `point_number`, `name`, `pinyin`, `meridian_code`, `meridian_name`, `meridian_english`, `model_id`, `body_area`, `standard_location`, `child_location`, `child_description`, `safety_tip`, `source_name`, `source_link`, `position_x`, `position_y`, `position_z`, `sort_order`, `enabled`) VALUES ('ST-39', 39, '下巨虚', 'Xiajuxu', 'ST', '足阳明胃经', 'Stomach Meridian', 'e39', '髋腿部', '在小腿外侧，犊鼻（ST35）下9寸，犊鼻（ST35）与解溪（ST41）连线上。', '转动3D小铜人，看向下肢前外侧。在髋腿部找到“下巨虚星”的发光点，点一下就完成观察。', '小侦探找到了下巨虚。档案上写着“足阳明胃经”，它的地图区域是髋腿部。', '只看3D铜人和文化图卡，不做身体操作；有问题请告诉老师或家长。', 'GB/T 12346-2021《经穴名称与定位》', 'https://openstd.samr.gov.cn/bzgk/std/newGbInfo?hcno=397548AE7248D3D87DD15E0AB8107185', -11.367798006864492, -73.28000000000037, -1.9000000000000021, 70, 1) ON DUPLICATE KEY UPDATE `point_number`=VALUES(`point_number`), `name`=VALUES(`name`), `pinyin`=VALUES(`pinyin`), `meridian_code`=VALUES(`meridian_code`), `meridian_name`=VALUES(`meridian_name`), `meridian_english`=VALUES(`meridian_english`), `model_id`=VALUES(`model_id`), `body_area`=VALUES(`body_area`), `standard_location`=VALUES(`standard_location`), `child_location`=VALUES(`child_location`), `child_description`=VALUES(`child_description`), `safety_tip`=VALUES(`safety_tip`), `source_name`=VALUES(`source_name`), `source_link`=VALUES(`source_link`), `position_x`=VALUES(`position_x`), `position_y`=VALUES(`position_y`), `position_z`=VALUES(`position_z`), `sort_order`=VALUES(`sort_order`), `enabled`=VALUES(`enabled`);
INSERT INTO `acupoint_knowledge` (`code`, `point_number`, `name`, `pinyin`, `meridian_code`, `meridian_name`, `meridian_english`, `model_id`, `body_area`, `standard_location`, `child_location`, `child_description`, `safety_tip`, `source_name`, `source_link`, `position_x`, `position_y`, `position_z`, `sort_order`, `enabled`) VALUES ('ST-40', 40, '丰隆', 'Fenglong', 'ST', '足阳明胃经', 'Stomach Meridian', 'e40', '髋腿部', '在小腿外侧，外踝尖上8寸，胫骨前肌的外缘。注：犊鼻与解溪连线的中点，条口外侧一横指处。', '转动3D小铜人，看向下肢前外侧。在髋腿部找到“丰隆星”的发光点，点一下就完成观察。', '丰隆带着一张“足阳明胃经”路线卡。把它收进档案，再认一认髋腿部。', '只看3D铜人和文化图卡，不做身体操作；有问题请告诉老师或家长。', 'GB/T 12346-2021《经穴名称与定位》', 'https://openstd.samr.gov.cn/bzgk/std/newGbInfo?hcno=397548AE7248D3D87DD15E0AB8107185', -13.467798006864484, -69.48000000000059, -4.3000000000000025, 71, 1) ON DUPLICATE KEY UPDATE `point_number`=VALUES(`point_number`), `name`=VALUES(`name`), `pinyin`=VALUES(`pinyin`), `meridian_code`=VALUES(`meridian_code`), `meridian_name`=VALUES(`meridian_name`), `meridian_english`=VALUES(`meridian_english`), `model_id`=VALUES(`model_id`), `body_area`=VALUES(`body_area`), `standard_location`=VALUES(`standard_location`), `child_location`=VALUES(`child_location`), `child_description`=VALUES(`child_description`), `safety_tip`=VALUES(`safety_tip`), `source_name`=VALUES(`source_name`), `source_link`=VALUES(`source_link`), `position_x`=VALUES(`position_x`), `position_y`=VALUES(`position_y`), `position_z`=VALUES(`position_z`), `sort_order`=VALUES(`sort_order`), `enabled`=VALUES(`enabled`);
INSERT INTO `acupoint_knowledge` (`code`, `point_number`, `name`, `pinyin`, `meridian_code`, `meridian_name`, `meridian_english`, `model_id`, `body_area`, `standard_location`, `child_location`, `child_description`, `safety_tip`, `source_name`, `source_link`, `position_x`, `position_y`, `position_z`, `sort_order`, `enabled`) VALUES ('ST-41', 41, '解谿', 'Jiexi', 'ST', '足阳明胃经', 'Stomach Meridian', 'e41', '踝足部', '在踝前侧，踝关节前面中央凹陷中，长伸肌腱与趾长伸肌腱之间。注：相当于内、外踝尖连线中点处。', '转动3D小铜人，看向足踝、足背局部。在踝足部找到“解谿星”的发光点，点一下就完成观察。', '解谿对小侦探说：“请把我放进足阳明胃经档案。我的地图标签是踝足部。”', '只看3D铜人和文化图卡，不做身体操作；有问题请告诉老师或家长。', 'GB/T 12346-2021《经穴名称与定位》', 'https://openstd.samr.gov.cn/bzgk/std/newGbInfo?hcno=397548AE7248D3D87DD15E0AB8107185', -8.667798006864501, -85.1799999999997, -0.8000000000000016, 72, 1) ON DUPLICATE KEY UPDATE `point_number`=VALUES(`point_number`), `name`=VALUES(`name`), `pinyin`=VALUES(`pinyin`), `meridian_code`=VALUES(`meridian_code`), `meridian_name`=VALUES(`meridian_name`), `meridian_english`=VALUES(`meridian_english`), `model_id`=VALUES(`model_id`), `body_area`=VALUES(`body_area`), `standard_location`=VALUES(`standard_location`), `child_location`=VALUES(`child_location`), `child_description`=VALUES(`child_description`), `safety_tip`=VALUES(`safety_tip`), `source_name`=VALUES(`source_name`), `source_link`=VALUES(`source_link`), `position_x`=VALUES(`position_x`), `position_y`=VALUES(`position_y`), `position_z`=VALUES(`position_z`), `sort_order`=VALUES(`sort_order`), `enabled`=VALUES(`enabled`);
INSERT INTO `acupoint_knowledge` (`code`, `point_number`, `name`, `pinyin`, `meridian_code`, `meridian_name`, `meridian_english`, `model_id`, `body_area`, `standard_location`, `child_location`, `child_description`, `safety_tip`, `source_name`, `source_link`, `position_x`, `position_y`, `position_z`, `sort_order`, `enabled`) VALUES ('ST-42', 42, '冲阳', 'Chongyang', 'ST', '足阳明胃经', 'Stomach Meridian', 'e42', '踝足部', '在足背，第2跖骨基底部与中间楔状骨关节处，可触及足背动脉。', '转动3D小铜人，看向足踝、足背局部。在踝足部找到“冲阳星”的发光点，点一下就完成观察。', '身体文化地图上，冲阳是踝足部的一枚经络小旗。它属于足阳明胃经。', '只看3D铜人和文化图卡，不做身体操作；有问题请告诉老师或家长。', 'GB/T 12346-2021《经穴名称与定位》', 'https://openstd.samr.gov.cn/bzgk/std/newGbInfo?hcno=397548AE7248D3D87DD15E0AB8107185', -9.967798006864497, -88.27999999999952, 0.9999999999999983, 73, 1) ON DUPLICATE KEY UPDATE `point_number`=VALUES(`point_number`), `name`=VALUES(`name`), `pinyin`=VALUES(`pinyin`), `meridian_code`=VALUES(`meridian_code`), `meridian_name`=VALUES(`meridian_name`), `meridian_english`=VALUES(`meridian_english`), `model_id`=VALUES(`model_id`), `body_area`=VALUES(`body_area`), `standard_location`=VALUES(`standard_location`), `child_location`=VALUES(`child_location`), `child_description`=VALUES(`child_description`), `safety_tip`=VALUES(`safety_tip`), `source_name`=VALUES(`source_name`), `source_link`=VALUES(`source_link`), `position_x`=VALUES(`position_x`), `position_y`=VALUES(`position_y`), `position_z`=VALUES(`position_z`), `sort_order`=VALUES(`sort_order`), `enabled`=VALUES(`enabled`);
INSERT INTO `acupoint_knowledge` (`code`, `point_number`, `name`, `pinyin`, `meridian_code`, `meridian_name`, `meridian_english`, `model_id`, `body_area`, `standard_location`, `child_location`, `child_description`, `safety_tip`, `source_name`, `source_link`, `position_x`, `position_y`, `position_z`, `sort_order`, `enabled`) VALUES ('ST-43', 43, '陷谷', 'Xiangu', 'ST', '足阳明胃经', 'Stomach Meridian', 'e43', '踝足部', '在足背，第2、3跖骨间，第2跖趾关节近端凹陷中。', '转动3D小铜人，看向足踝、足背局部。在踝足部找到“陷谷星”的发光点，点一下就完成观察。', '小侦探找到了陷谷。档案上写着“足阳明胃经”，它的地图区域是踝足部。', '只看3D铜人和文化图卡，不做身体操作；有问题请告诉老师或家长。', 'GB/T 12346-2021《经穴名称与定位》', 'https://openstd.samr.gov.cn/bzgk/std/newGbInfo?hcno=397548AE7248D3D87DD15E0AB8107185', -8.8677980068645, -90.97999999999936, 6.099999999999993, 74, 1) ON DUPLICATE KEY UPDATE `point_number`=VALUES(`point_number`), `name`=VALUES(`name`), `pinyin`=VALUES(`pinyin`), `meridian_code`=VALUES(`meridian_code`), `meridian_name`=VALUES(`meridian_name`), `meridian_english`=VALUES(`meridian_english`), `model_id`=VALUES(`model_id`), `body_area`=VALUES(`body_area`), `standard_location`=VALUES(`standard_location`), `child_location`=VALUES(`child_location`), `child_description`=VALUES(`child_description`), `safety_tip`=VALUES(`safety_tip`), `source_name`=VALUES(`source_name`), `source_link`=VALUES(`source_link`), `position_x`=VALUES(`position_x`), `position_y`=VALUES(`position_y`), `position_z`=VALUES(`position_z`), `sort_order`=VALUES(`sort_order`), `enabled`=VALUES(`enabled`);
INSERT INTO `acupoint_knowledge` (`code`, `point_number`, `name`, `pinyin`, `meridian_code`, `meridian_name`, `meridian_english`, `model_id`, `body_area`, `standard_location`, `child_location`, `child_description`, `safety_tip`, `source_name`, `source_link`, `position_x`, `position_y`, `position_z`, `sort_order`, `enabled`) VALUES ('ST-44', 44, '内庭', 'Neiting', 'ST', '足阳明胃经', 'Stomach Meridian', 'e44', '踝足部', '在足背，第2、3趾间，趾蹼缘后方赤白肉际处。', '转动3D小铜人，看向足踝、足背局部。在踝足部找到“内庭星”的发光点，点一下就完成观察。', '内庭是足阳明胃经的星河门牌。它告诉我们：这条文化路线会经过踝足部。', '只看3D铜人和文化图卡，不做身体操作；有问题请告诉老师或家长。', 'GB/T 12346-2021《经穴名称与定位》', 'https://openstd.samr.gov.cn/bzgk/std/newGbInfo?hcno=397548AE7248D3D87DD15E0AB8107185', -9.467798006864498, -91.87999999999931, 7.799999999999988, 75, 1) ON DUPLICATE KEY UPDATE `point_number`=VALUES(`point_number`), `name`=VALUES(`name`), `pinyin`=VALUES(`pinyin`), `meridian_code`=VALUES(`meridian_code`), `meridian_name`=VALUES(`meridian_name`), `meridian_english`=VALUES(`meridian_english`), `model_id`=VALUES(`model_id`), `body_area`=VALUES(`body_area`), `standard_location`=VALUES(`standard_location`), `child_location`=VALUES(`child_location`), `child_description`=VALUES(`child_description`), `safety_tip`=VALUES(`safety_tip`), `source_name`=VALUES(`source_name`), `source_link`=VALUES(`source_link`), `position_x`=VALUES(`position_x`), `position_y`=VALUES(`position_y`), `position_z`=VALUES(`position_z`), `sort_order`=VALUES(`sort_order`), `enabled`=VALUES(`enabled`);
INSERT INTO `acupoint_knowledge` (`code`, `point_number`, `name`, `pinyin`, `meridian_code`, `meridian_name`, `meridian_english`, `model_id`, `body_area`, `standard_location`, `child_location`, `child_description`, `safety_tip`, `source_name`, `source_link`, `position_x`, `position_y`, `position_z`, `sort_order`, `enabled`) VALUES ('ST-45', 45, '厉兑', 'Lidui', 'ST', '足阳明胃经', 'Stomach Meridian', 'e45', '踝足部', '在足趾，第2趾末节外侧，趾甲根角侧后方0.1寸。', '转动3D小铜人，看向足踝、足背局部。在踝足部找到“厉兑星”的发光点，点一下就完成观察。', '点亮厉兑后，踝足部的地图多了一颗星。它是足阳明胃经路线的一站。', '只看3D铜人和文化图卡，不做身体操作；有问题请告诉老师或家长。', 'GB/T 12346-2021《经穴名称与定位》', 'https://openstd.samr.gov.cn/bzgk/std/newGbInfo?hcno=397548AE7248D3D87DD15E0AB8107185', -9.967798006864497, -93.17999999999924, 11.299999999999976, 76, 1) ON DUPLICATE KEY UPDATE `point_number`=VALUES(`point_number`), `name`=VALUES(`name`), `pinyin`=VALUES(`pinyin`), `meridian_code`=VALUES(`meridian_code`), `meridian_name`=VALUES(`meridian_name`), `meridian_english`=VALUES(`meridian_english`), `model_id`=VALUES(`model_id`), `body_area`=VALUES(`body_area`), `standard_location`=VALUES(`standard_location`), `child_location`=VALUES(`child_location`), `child_description`=VALUES(`child_description`), `safety_tip`=VALUES(`safety_tip`), `source_name`=VALUES(`source_name`), `source_link`=VALUES(`source_link`), `position_x`=VALUES(`position_x`), `position_y`=VALUES(`position_y`), `position_z`=VALUES(`position_z`), `sort_order`=VALUES(`sort_order`), `enabled`=VALUES(`enabled`);
