INSERT INTO `acupoint_knowledge` (`code`, `point_number`, `name`, `pinyin`, `meridian_code`, `meridian_name`, `meridian_english`, `model_id`, `body_area`, `standard_location`, `child_location`, `child_description`, `safety_tip`, `source_name`, `source_link`, `position_x`, `position_y`, `position_z`, `sort_order`, `enabled`) VALUES ('PC-7', 7, '大陵', 'Daling', 'PC', '手厥阴心包经', 'Pericardium Meridian', 'cs7', '手腕部', '在腕前区，腕掌侧远端横纹的中点，掌长肌腱与桡侧腕屈肌腱之间。', '转动3D小铜人，看向手部、腕部。在手腕部找到“大陵星”的发光点，点一下就完成观察。', '小铜人把大陵标成PC-7。这枚星光路牌帮我们记住手腕部和手厥阴心包经。', '只看3D铜人和文化图卡，不做身体操作；有问题请告诉老师或家长。', 'GB/T 12346-2021《经穴名称与定位》', 'https://openstd.samr.gov.cn/bzgk/std/newGbInfo?hcno=397548AE7248D3D87DD15E0AB8107185', -24.71516683000315, -6.555406638283143, 0.6, 226, 1) ON DUPLICATE KEY UPDATE `point_number`=VALUES(`point_number`), `name`=VALUES(`name`), `pinyin`=VALUES(`pinyin`), `meridian_code`=VALUES(`meridian_code`), `meridian_name`=VALUES(`meridian_name`), `meridian_english`=VALUES(`meridian_english`), `model_id`=VALUES(`model_id`), `body_area`=VALUES(`body_area`), `standard_location`=VALUES(`standard_location`), `child_location`=VALUES(`child_location`), `child_description`=VALUES(`child_description`), `safety_tip`=VALUES(`safety_tip`), `source_name`=VALUES(`source_name`), `source_link`=VALUES(`source_link`), `position_x`=VALUES(`position_x`), `position_y`=VALUES(`position_y`), `position_z`=VALUES(`position_z`), `sort_order`=VALUES(`sort_order`), `enabled`=VALUES(`enabled`);
