INSERT INTO `acupoint_knowledge` (`code`, `point_number`, `name`, `pinyin`, `meridian_code`, `meridian_name`, `meridian_english`, `model_id`, `body_area`, `standard_location`, `child_location`, `child_description`, `safety_tip`, `source_name`, `source_link`, `position_x`, `position_y`, `position_z`, `sort_order`, `enabled`) VALUES ('CV-1', 1, '会阴', 'Huiyin', 'CV', '任脉', 'Conception Vessel', NULL, '经络档案区', NULL, '“会阴星”现在住在任脉图鉴里。它还没有3D坐标，先读名字和文化卡。', '会阴的两个档案词是CV-1和任脉。现在它只出现在文化图鉴中。', '只看3D铜人和文化图卡，不做身体操作；有问题请告诉老师或家长。', '项目现有穴位目录', NULL, NULL, NULL, NULL, 338, 1) ON DUPLICATE KEY UPDATE `point_number`=VALUES(`point_number`), `name`=VALUES(`name`), `pinyin`=VALUES(`pinyin`), `meridian_code`=VALUES(`meridian_code`), `meridian_name`=VALUES(`meridian_name`), `meridian_english`=VALUES(`meridian_english`), `model_id`=VALUES(`model_id`), `body_area`=VALUES(`body_area`), `standard_location`=VALUES(`standard_location`), `child_location`=VALUES(`child_location`), `child_description`=VALUES(`child_description`), `safety_tip`=VALUES(`safety_tip`), `source_name`=VALUES(`source_name`), `source_link`=VALUES(`source_link`), `position_x`=VALUES(`position_x`), `position_y`=VALUES(`position_y`), `position_z`=VALUES(`position_z`), `sort_order`=VALUES(`sort_order`), `enabled`=VALUES(`enabled`);
INSERT INTO `acupoint_knowledge` (`code`, `point_number`, `name`, `pinyin`, `meridian_code`, `meridian_name`, `meridian_english`, `model_id`, `body_area`, `standard_location`, `child_location`, `child_description`, `safety_tip`, `source_name`, `source_link`, `position_x`, `position_y`, `position_z`, `sort_order`, `enabled`) VALUES ('CV-2', 2, '曲骨', 'Qugu', 'CV', '任脉', 'Conception Vessel', 'vc2', '腹部', '在下腹部，耻骨联合上缘，前正中线上。', '转动3D小铜人，看向腹部正中线。在腹部找到“曲骨星”的发光点，点一下就完成观察。', '在腹部的星点档案里，曲骨和任脉站在同一条路线上。', '只看3D铜人和文化图卡，不做身体操作；有问题请告诉老师或家长。', 'GB/T 12346-2021《经穴名称与定位》', 'https://openstd.samr.gov.cn/bzgk/std/newGbInfo?hcno=397548AE7248D3D87DD15E0AB8107185', 0.05, -6, 6.4, 339, 1) ON DUPLICATE KEY UPDATE `point_number`=VALUES(`point_number`), `name`=VALUES(`name`), `pinyin`=VALUES(`pinyin`), `meridian_code`=VALUES(`meridian_code`), `meridian_name`=VALUES(`meridian_name`), `meridian_english`=VALUES(`meridian_english`), `model_id`=VALUES(`model_id`), `body_area`=VALUES(`body_area`), `standard_location`=VALUES(`standard_location`), `child_location`=VALUES(`child_location`), `child_description`=VALUES(`child_description`), `safety_tip`=VALUES(`safety_tip`), `source_name`=VALUES(`source_name`), `source_link`=VALUES(`source_link`), `position_x`=VALUES(`position_x`), `position_y`=VALUES(`position_y`), `position_z`=VALUES(`position_z`), `sort_order`=VALUES(`sort_order`), `enabled`=VALUES(`enabled`);
INSERT INTO `acupoint_knowledge` (`code`, `point_number`, `name`, `pinyin`, `meridian_code`, `meridian_name`, `meridian_english`, `model_id`, `body_area`, `standard_location`, `child_location`, `child_description`, `safety_tip`, `source_name`, `source_link`, `position_x`, `position_y`, `position_z`, `sort_order`, `enabled`) VALUES ('CV-3', 3, '中极', 'Zhongji', 'CV', '任脉', 'Conception Vessel', 'vc3', '腹部', '在下腹部，脐中下4寸，前正中线上。', '转动3D小铜人，看向腹部正中线。在腹部找到“中极星”的发光点，点一下就完成观察。', '小侦探找到了中极。档案上写着“任脉”，它的地图区域是腹部。', '只看3D铜人和文化图卡，不做身体操作；有问题请告诉老师或家长。', 'GB/T 12346-2021《经穴名称与定位》', 'https://openstd.samr.gov.cn/bzgk/std/newGbInfo?hcno=397548AE7248D3D87DD15E0AB8107185', 0.05, -2.9, 7.1, 340, 1) ON DUPLICATE KEY UPDATE `point_number`=VALUES(`point_number`), `name`=VALUES(`name`), `pinyin`=VALUES(`pinyin`), `meridian_code`=VALUES(`meridian_code`), `meridian_name`=VALUES(`meridian_name`), `meridian_english`=VALUES(`meridian_english`), `model_id`=VALUES(`model_id`), `body_area`=VALUES(`body_area`), `standard_location`=VALUES(`standard_location`), `child_location`=VALUES(`child_location`), `child_description`=VALUES(`child_description`), `safety_tip`=VALUES(`safety_tip`), `source_name`=VALUES(`source_name`), `source_link`=VALUES(`source_link`), `position_x`=VALUES(`position_x`), `position_y`=VALUES(`position_y`), `position_z`=VALUES(`position_z`), `sort_order`=VALUES(`sort_order`), `enabled`=VALUES(`enabled`);
INSERT INTO `acupoint_knowledge` (`code`, `point_number`, `name`, `pinyin`, `meridian_code`, `meridian_name`, `meridian_english`, `model_id`, `body_area`, `standard_location`, `child_location`, `child_description`, `safety_tip`, `source_name`, `source_link`, `position_x`, `position_y`, `position_z`, `sort_order`, `enabled`) VALUES ('CV-4', 4, '关元', 'Guanyuan', 'CV', '任脉', 'Conception Vessel', 'vc4', '腹部', '在下腹部，脐中下3寸，前正中线上。', '转动3D小铜人，看向腹部正中线。在腹部找到“关元星”的发光点，点一下就完成观察。', '关元的档案有两个关键词：腹部和任脉。把它们连起来，线索就完整了。', '只看3D铜人和文化图卡，不做身体操作；有问题请告诉老师或家长。', 'GB/T 12346-2021《经穴名称与定位》', 'https://openstd.samr.gov.cn/bzgk/std/newGbInfo?hcno=397548AE7248D3D87DD15E0AB8107185', 0.05, 0.20000000000000018, 7.17, 341, 1) ON DUPLICATE KEY UPDATE `point_number`=VALUES(`point_number`), `name`=VALUES(`name`), `pinyin`=VALUES(`pinyin`), `meridian_code`=VALUES(`meridian_code`), `meridian_name`=VALUES(`meridian_name`), `meridian_english`=VALUES(`meridian_english`), `model_id`=VALUES(`model_id`), `body_area`=VALUES(`body_area`), `standard_location`=VALUES(`standard_location`), `child_location`=VALUES(`child_location`), `child_description`=VALUES(`child_description`), `safety_tip`=VALUES(`safety_tip`), `source_name`=VALUES(`source_name`), `source_link`=VALUES(`source_link`), `position_x`=VALUES(`position_x`), `position_y`=VALUES(`position_y`), `position_z`=VALUES(`position_z`), `sort_order`=VALUES(`sort_order`), `enabled`=VALUES(`enabled`);
