INSERT INTO `acupoint_knowledge` (`code`, `point_number`, `name`, `pinyin`, `meridian_code`, `meridian_name`, `meridian_english`, `model_id`, `body_area`, `standard_location`, `child_location`, `child_description`, `safety_tip`, `source_name`, `source_link`, `position_x`, `position_y`, `position_z`, `sort_order`, `enabled`) VALUES ('CV-6', 6, '气海', 'Qihai', 'CV', '任脉', 'Conception Vessel', 'vc6', '腹部', '在下腹部，脐中下1.5寸，前正中线上。', '转动3D小铜人，看向腹部正中线。在腹部找到“气海星”的发光点，点一下就完成观察。', '气海对小侦探说：“请把我放进任脉档案。我的地图标签是腹部。”', '只看3D铜人和文化图卡，不做身体操作；有问题请告诉老师或家长。', 'GB/T 12346-2021《经穴名称与定位》', 'https://openstd.samr.gov.cn/bzgk/std/newGbInfo?hcno=397548AE7248D3D87DD15E0AB8107185', 0.05, 6.4, 7.3, 343, 1) ON DUPLICATE KEY UPDATE `point_number`=VALUES(`point_number`), `name`=VALUES(`name`), `pinyin`=VALUES(`pinyin`), `meridian_code`=VALUES(`meridian_code`), `meridian_name`=VALUES(`meridian_name`), `meridian_english`=VALUES(`meridian_english`), `model_id`=VALUES(`model_id`), `body_area`=VALUES(`body_area`), `standard_location`=VALUES(`standard_location`), `child_location`=VALUES(`child_location`), `child_description`=VALUES(`child_description`), `safety_tip`=VALUES(`safety_tip`), `source_name`=VALUES(`source_name`), `source_link`=VALUES(`source_link`), `position_x`=VALUES(`position_x`), `position_y`=VALUES(`position_y`), `position_z`=VALUES(`position_z`), `sort_order`=VALUES(`sort_order`), `enabled`=VALUES(`enabled`);
INSERT INTO `acupoint_knowledge` (`code`, `point_number`, `name`, `pinyin`, `meridian_code`, `meridian_name`, `meridian_english`, `model_id`, `body_area`, `standard_location`, `child_location`, `child_description`, `safety_tip`, `source_name`, `source_link`, `position_x`, `position_y`, `position_z`, `sort_order`, `enabled`) VALUES ('CV-7', 7, '阴交', 'Yinjiao', 'CV', '任脉', 'Conception Vessel', 'vc7', '腹部', '在下腹部，脐中下1寸，前正中线上。', '转动3D小铜人，看向腹部正中线。在腹部找到“阴交星”的发光点，点一下就完成观察。', '点亮阴交后，腹部的地图多了一颗星。它是任脉路线的一站。', '只看3D铜人和文化图卡，不做身体操作；有问题请告诉老师或家长。', 'GB/T 12346-2021《经穴名称与定位》', 'https://openstd.samr.gov.cn/bzgk/std/newGbInfo?hcno=397548AE7248D3D87DD15E0AB8107185', 0.05, 9.5, 7.2, 344, 1) ON DUPLICATE KEY UPDATE `point_number`=VALUES(`point_number`), `name`=VALUES(`name`), `pinyin`=VALUES(`pinyin`), `meridian_code`=VALUES(`meridian_code`), `meridian_name`=VALUES(`meridian_name`), `meridian_english`=VALUES(`meridian_english`), `model_id`=VALUES(`model_id`), `body_area`=VALUES(`body_area`), `standard_location`=VALUES(`standard_location`), `child_location`=VALUES(`child_location`), `child_description`=VALUES(`child_description`), `safety_tip`=VALUES(`safety_tip`), `source_name`=VALUES(`source_name`), `source_link`=VALUES(`source_link`), `position_x`=VALUES(`position_x`), `position_y`=VALUES(`position_y`), `position_z`=VALUES(`position_z`), `sort_order`=VALUES(`sort_order`), `enabled`=VALUES(`enabled`);
INSERT INTO `acupoint_knowledge` (`code`, `point_number`, `name`, `pinyin`, `meridian_code`, `meridian_name`, `meridian_english`, `model_id`, `body_area`, `standard_location`, `child_location`, `child_description`, `safety_tip`, `source_name`, `source_link`, `position_x`, `position_y`, `position_z`, `sort_order`, `enabled`) VALUES ('CV-8', 8, '神阙', 'Shenque', 'CV', '任脉', 'Conception Vessel', 'vc8', '腹部', '在脐区，脐中央。', '转动3D小铜人，看向腹部正中线。在腹部找到“神阙星”的发光点，点一下就完成观察。', '身体文化地图上，神阙是腹部的一枚文化车站。它属于任脉。', '只看3D铜人和文化图卡，不做身体操作；有问题请告诉老师或家长。', 'GB/T 12346-2021《经穴名称与定位》', 'https://openstd.samr.gov.cn/bzgk/std/newGbInfo?hcno=397548AE7248D3D87DD15E0AB8107185', 0.05, 12.7, 6.1, 345, 1) ON DUPLICATE KEY UPDATE `point_number`=VALUES(`point_number`), `name`=VALUES(`name`), `pinyin`=VALUES(`pinyin`), `meridian_code`=VALUES(`meridian_code`), `meridian_name`=VALUES(`meridian_name`), `meridian_english`=VALUES(`meridian_english`), `model_id`=VALUES(`model_id`), `body_area`=VALUES(`body_area`), `standard_location`=VALUES(`standard_location`), `child_location`=VALUES(`child_location`), `child_description`=VALUES(`child_description`), `safety_tip`=VALUES(`safety_tip`), `source_name`=VALUES(`source_name`), `source_link`=VALUES(`source_link`), `position_x`=VALUES(`position_x`), `position_y`=VALUES(`position_y`), `position_z`=VALUES(`position_z`), `sort_order`=VALUES(`sort_order`), `enabled`=VALUES(`enabled`);
INSERT INTO `acupoint_knowledge` (`code`, `point_number`, `name`, `pinyin`, `meridian_code`, `meridian_name`, `meridian_english`, `model_id`, `body_area`, `standard_location`, `child_location`, `child_description`, `safety_tip`, `source_name`, `source_link`, `position_x`, `position_y`, `position_z`, `sort_order`, `enabled`) VALUES ('CV-9', 9, '水分', 'Shuifen', 'CV', '任脉', 'Conception Vessel', 'vc9', '腹部', '在上腹部，脐中上1寸，前正中线上。', '转动3D小铜人，看向腹部正中线。在腹部找到“水分星”的发光点，点一下就完成观察。', '水分对小侦探说：“请把我放进任脉档案。我的地图标签是腹部。”', '只看3D铜人和文化图卡，不做身体操作；有问题请告诉老师或家长。', 'GB/T 12346-2021《经穴名称与定位》', 'https://openstd.samr.gov.cn/bzgk/std/newGbInfo?hcno=397548AE7248D3D87DD15E0AB8107185', 0.05, 15.9, 6.1, 346, 1) ON DUPLICATE KEY UPDATE `point_number`=VALUES(`point_number`), `name`=VALUES(`name`), `pinyin`=VALUES(`pinyin`), `meridian_code`=VALUES(`meridian_code`), `meridian_name`=VALUES(`meridian_name`), `meridian_english`=VALUES(`meridian_english`), `model_id`=VALUES(`model_id`), `body_area`=VALUES(`body_area`), `standard_location`=VALUES(`standard_location`), `child_location`=VALUES(`child_location`), `child_description`=VALUES(`child_description`), `safety_tip`=VALUES(`safety_tip`), `source_name`=VALUES(`source_name`), `source_link`=VALUES(`source_link`), `position_x`=VALUES(`position_x`), `position_y`=VALUES(`position_y`), `position_z`=VALUES(`position_z`), `sort_order`=VALUES(`sort_order`), `enabled`=VALUES(`enabled`);
INSERT INTO `acupoint_knowledge` (`code`, `point_number`, `name`, `pinyin`, `meridian_code`, `meridian_name`, `meridian_english`, `model_id`, `body_area`, `standard_location`, `child_location`, `child_description`, `safety_tip`, `source_name`, `source_link`, `position_x`, `position_y`, `position_z`, `sort_order`, `enabled`) VALUES ('CV-10', 10, '下脘', 'Xiawan', 'CV', '任脉', 'Conception Vessel', 'vc10', '腹部', '在上腹部，脐中上2寸，前正中线上。', '转动3D小铜人，看向腹部正中线。在腹部找到“下脘星”的发光点，点一下就完成观察。', 'CV-10是下脘的星点编号。记住编号和任脉，就找到了它的文化档案。', '只看3D铜人和文化图卡，不做身体操作；有问题请告诉老师或家长。', 'GB/T 12346-2021《经穴名称与定位》', 'https://openstd.samr.gov.cn/bzgk/std/newGbInfo?hcno=397548AE7248D3D87DD15E0AB8107185', 0.05, 18.4, 6.38, 347, 1) ON DUPLICATE KEY UPDATE `point_number`=VALUES(`point_number`), `name`=VALUES(`name`), `pinyin`=VALUES(`pinyin`), `meridian_code`=VALUES(`meridian_code`), `meridian_name`=VALUES(`meridian_name`), `meridian_english`=VALUES(`meridian_english`), `model_id`=VALUES(`model_id`), `body_area`=VALUES(`body_area`), `standard_location`=VALUES(`standard_location`), `child_location`=VALUES(`child_location`), `child_description`=VALUES(`child_description`), `safety_tip`=VALUES(`safety_tip`), `source_name`=VALUES(`source_name`), `source_link`=VALUES(`source_link`), `position_x`=VALUES(`position_x`), `position_y`=VALUES(`position_y`), `position_z`=VALUES(`position_z`), `sort_order`=VALUES(`sort_order`), `enabled`=VALUES(`enabled`);
INSERT INTO `acupoint_knowledge` (`code`, `point_number`, `name`, `pinyin`, `meridian_code`, `meridian_name`, `meridian_english`, `model_id`, `body_area`, `standard_location`, `child_location`, `child_description`, `safety_tip`, `source_name`, `source_link`, `position_x`, `position_y`, `position_z`, `sort_order`, `enabled`) VALUES ('CV-11', 11, '建里', 'Jianli', 'CV', '任脉', 'Conception Vessel', 'vc11', '腹部', '在上腹部，脐中上3寸，前正中线上。', '转动3D小铜人，看向腹部正中线。在腹部找到“建里星”的发光点，点一下就完成观察。', '建里是任脉的文化车站。它告诉我们：这条文化路线会经过腹部。', '只看3D铜人和文化图卡，不做身体操作；有问题请告诉老师或家长。', 'GB/T 12346-2021《经穴名称与定位》', 'https://openstd.samr.gov.cn/bzgk/std/newGbInfo?hcno=397548AE7248D3D87DD15E0AB8107185', 0.05, 20.9, 6.38, 348, 1) ON DUPLICATE KEY UPDATE `point_number`=VALUES(`point_number`), `name`=VALUES(`name`), `pinyin`=VALUES(`pinyin`), `meridian_code`=VALUES(`meridian_code`), `meridian_name`=VALUES(`meridian_name`), `meridian_english`=VALUES(`meridian_english`), `model_id`=VALUES(`model_id`), `body_area`=VALUES(`body_area`), `standard_location`=VALUES(`standard_location`), `child_location`=VALUES(`child_location`), `child_description`=VALUES(`child_description`), `safety_tip`=VALUES(`safety_tip`), `source_name`=VALUES(`source_name`), `source_link`=VALUES(`source_link`), `position_x`=VALUES(`position_x`), `position_y`=VALUES(`position_y`), `position_z`=VALUES(`position_z`), `sort_order`=VALUES(`sort_order`), `enabled`=VALUES(`enabled`);
INSERT INTO `acupoint_knowledge` (`code`, `point_number`, `name`, `pinyin`, `meridian_code`, `meridian_name`, `meridian_english`, `model_id`, `body_area`, `standard_location`, `child_location`, `child_description`, `safety_tip`, `source_name`, `source_link`, `position_x`, `position_y`, `position_z`, `sort_order`, `enabled`) VALUES ('CV-12', 12, '中脘', 'Zhongwan', 'CV', '任脉', 'Conception Vessel', 'vc12', '腹部', '在上腹部，脐中上4寸，前正中线上。', '转动3D小铜人，看向腹部正中线。在腹部找到“中脘星”的发光点，点一下就完成观察。', '在腹部的星点档案里，中脘和任脉站在同一条路线上。', '只看3D铜人和文化图卡，不做身体操作；有问题请告诉老师或家长。', 'GB/T 12346-2021《经穴名称与定位》', 'https://openstd.samr.gov.cn/bzgk/std/newGbInfo?hcno=397548AE7248D3D87DD15E0AB8107185', 0.05, 23.4, 6.58, 349, 1) ON DUPLICATE KEY UPDATE `point_number`=VALUES(`point_number`), `name`=VALUES(`name`), `pinyin`=VALUES(`pinyin`), `meridian_code`=VALUES(`meridian_code`), `meridian_name`=VALUES(`meridian_name`), `meridian_english`=VALUES(`meridian_english`), `model_id`=VALUES(`model_id`), `body_area`=VALUES(`body_area`), `standard_location`=VALUES(`standard_location`), `child_location`=VALUES(`child_location`), `child_description`=VALUES(`child_description`), `safety_tip`=VALUES(`safety_tip`), `source_name`=VALUES(`source_name`), `source_link`=VALUES(`source_link`), `position_x`=VALUES(`position_x`), `position_y`=VALUES(`position_y`), `position_z`=VALUES(`position_z`), `sort_order`=VALUES(`sort_order`), `enabled`=VALUES(`enabled`);
INSERT INTO `acupoint_knowledge` (`code`, `point_number`, `name`, `pinyin`, `meridian_code`, `meridian_name`, `meridian_english`, `model_id`, `body_area`, `standard_location`, `child_location`, `child_description`, `safety_tip`, `source_name`, `source_link`, `position_x`, `position_y`, `position_z`, `sort_order`, `enabled`) VALUES ('CV-13', 13, '上脘', 'Shangwan', 'CV', '任脉', 'Conception Vessel', 'vc13', '腹部', '在上腹部，脐中上5寸，前正中线上。', '转动3D小铜人，看向腹部正中线。在腹部找到“上脘星”的发光点，点一下就完成观察。', '跟着任脉路线，小侦探在腹部遇见了上脘。这是今天的文化新名字。', '只看3D铜人和文化图卡，不做身体操作；有问题请告诉老师或家长。', 'GB/T 12346-2021《经穴名称与定位》', 'https://openstd.samr.gov.cn/bzgk/std/newGbInfo?hcno=397548AE7248D3D87DD15E0AB8107185', 0.05, 25.9, 6.6, 350, 1) ON DUPLICATE KEY UPDATE `point_number`=VALUES(`point_number`), `name`=VALUES(`name`), `pinyin`=VALUES(`pinyin`), `meridian_code`=VALUES(`meridian_code`), `meridian_name`=VALUES(`meridian_name`), `meridian_english`=VALUES(`meridian_english`), `model_id`=VALUES(`model_id`), `body_area`=VALUES(`body_area`), `standard_location`=VALUES(`standard_location`), `child_location`=VALUES(`child_location`), `child_description`=VALUES(`child_description`), `safety_tip`=VALUES(`safety_tip`), `source_name`=VALUES(`source_name`), `source_link`=VALUES(`source_link`), `position_x`=VALUES(`position_x`), `position_y`=VALUES(`position_y`), `position_z`=VALUES(`position_z`), `sort_order`=VALUES(`sort_order`), `enabled`=VALUES(`enabled`);
