INSERT INTO `acupoint_knowledge` (`code`, `point_number`, `name`, `pinyin`, `meridian_code`, `meridian_name`, `meridian_english`, `model_id`, `body_area`, `standard_location`, `child_location`, `child_description`, `safety_tip`, `source_name`, `source_link`, `position_x`, `position_y`, `position_z`, `sort_order`, `enabled`) VALUES ('CV-21', 21, '璇玑', 'Xuanji', 'CV', '任脉', 'Conception Vessel', 'vc21', '胸部', '在胸部，胸骨上窝下1寸，前正中线上。注：天突（CV22）下1寸。', '转动3D小铜人，看向胸部正中线。在胸部找到“璇玑星”的发光点，点一下就完成观察。', '小铜人把璇玑标成CV-21。这枚星河门牌帮我们记住胸部和任脉。', '只看3D铜人和文化图卡，不做身体操作；有问题请告诉老师或家长。', 'GB/T 12346-2021《经穴名称与定位》', 'https://openstd.samr.gov.cn/bzgk/std/newGbInfo?hcno=397548AE7248D3D87DD15E0AB8107185', 0.05, 46.4, -0.9, 358, 1) ON DUPLICATE KEY UPDATE `point_number`=VALUES(`point_number`), `name`=VALUES(`name`), `pinyin`=VALUES(`pinyin`), `meridian_code`=VALUES(`meridian_code`), `meridian_name`=VALUES(`meridian_name`), `meridian_english`=VALUES(`meridian_english`), `model_id`=VALUES(`model_id`), `body_area`=VALUES(`body_area`), `standard_location`=VALUES(`standard_location`), `child_location`=VALUES(`child_location`), `child_description`=VALUES(`child_description`), `safety_tip`=VALUES(`safety_tip`), `source_name`=VALUES(`source_name`), `source_link`=VALUES(`source_link`), `position_x`=VALUES(`position_x`), `position_y`=VALUES(`position_y`), `position_z`=VALUES(`position_z`), `sort_order`=VALUES(`sort_order`), `enabled`=VALUES(`enabled`);
INSERT INTO `acupoint_knowledge` (`code`, `point_number`, `name`, `pinyin`, `meridian_code`, `meridian_name`, `meridian_english`, `model_id`, `body_area`, `standard_location`, `child_location`, `child_description`, `safety_tip`, `source_name`, `source_link`, `position_x`, `position_y`, `position_z`, `sort_order`, `enabled`) VALUES ('CV-22', 22, '天突', 'Tiantu', 'CV', '任脉', 'Conception Vessel', 'vc22', '头面与颈部', '在颈前部，胸骨上窝中央，前正中线上。', '转动3D小铜人，看向颈前正中。在头面与颈部找到“天突星”的发光点，点一下就完成观察。', '天突是任脉的地图坐标。它告诉我们：这条文化路线会经过头面与颈部。', '只看3D铜人和文化图卡，不做身体操作；有问题请告诉老师或家长。', 'GB/T 12346-2021《经穴名称与定位》', 'https://openstd.samr.gov.cn/bzgk/std/newGbInfo?hcno=397548AE7248D3D87DD15E0AB8107185', 0.05, 49, -2.1, 359, 1) ON DUPLICATE KEY UPDATE `point_number`=VALUES(`point_number`), `name`=VALUES(`name`), `pinyin`=VALUES(`pinyin`), `meridian_code`=VALUES(`meridian_code`), `meridian_name`=VALUES(`meridian_name`), `meridian_english`=VALUES(`meridian_english`), `model_id`=VALUES(`model_id`), `body_area`=VALUES(`body_area`), `standard_location`=VALUES(`standard_location`), `child_location`=VALUES(`child_location`), `child_description`=VALUES(`child_description`), `safety_tip`=VALUES(`safety_tip`), `source_name`=VALUES(`source_name`), `source_link`=VALUES(`source_link`), `position_x`=VALUES(`position_x`), `position_y`=VALUES(`position_y`), `position_z`=VALUES(`position_z`), `sort_order`=VALUES(`sort_order`), `enabled`=VALUES(`enabled`);
INSERT INTO `acupoint_knowledge` (`code`, `point_number`, `name`, `pinyin`, `meridian_code`, `meridian_name`, `meridian_english`, `model_id`, `body_area`, `standard_location`, `child_location`, `child_description`, `safety_tip`, `source_name`, `source_link`, `position_x`, `position_y`, `position_z`, `sort_order`, `enabled`) VALUES ('CV-23', 23, '廉泉', 'Lianquan', 'CV', '任脉', 'Conception Vessel', 'vc23', '头面与颈部', '在颈前部，喉结上方，舌骨上缘凹陷中，前正中线上。', '转动3D小铜人，看向颈前正中。在头面与颈部找到“廉泉星”的发光点，点一下就完成观察。', '小铜人把廉泉标成CV-23。这枚地图坐标帮我们记住头面与颈部和任脉。', '只看3D铜人和文化图卡，不做身体操作；有问题请告诉老师或家长。', 'GB/T 12346-2021《经穴名称与定位》', 'https://openstd.samr.gov.cn/bzgk/std/newGbInfo?hcno=397548AE7248D3D87DD15E0AB8107185', 0.02, 56, -0.2, 360, 1) ON DUPLICATE KEY UPDATE `point_number`=VALUES(`point_number`), `name`=VALUES(`name`), `pinyin`=VALUES(`pinyin`), `meridian_code`=VALUES(`meridian_code`), `meridian_name`=VALUES(`meridian_name`), `meridian_english`=VALUES(`meridian_english`), `model_id`=VALUES(`model_id`), `body_area`=VALUES(`body_area`), `standard_location`=VALUES(`standard_location`), `child_location`=VALUES(`child_location`), `child_description`=VALUES(`child_description`), `safety_tip`=VALUES(`safety_tip`), `source_name`=VALUES(`source_name`), `source_link`=VALUES(`source_link`), `position_x`=VALUES(`position_x`), `position_y`=VALUES(`position_y`), `position_z`=VALUES(`position_z`), `sort_order`=VALUES(`sort_order`), `enabled`=VALUES(`enabled`);
