-- Generated by scripts/generate-copper-man-seed.mjs.
-- Source: all 361 acupoints in the existing project catalog; 100 currently have 3D positions and GB/T 12346-2021 teaching metadata.
-- Child-facing copy intentionally excludes treatment claims and needle-operation guidance.

SELECT a.code, 1, 'PUBLISHED', JSON_OBJECT(
  'code', a.code, 'pointNumber', a.point_number, 'name', a.name, 'pinyin', a.pinyin,
  'meridianCode', a.meridian_code, 'meridianName', a.meridian_name,
  'meridianEnglish', a.meridian_english, 'modelId', a.model_id, 'bodyArea', a.body_area,
  'standardLocation', a.standard_location, 'childLocation', a.child_location,
  'childDescription', a.child_description, 'safetyTip', a.safety_tip,
  'sourceName', a.source_name, 'sourceLink', a.source_link,
  'positionX', a.position_x, 'positionY', a.position_y, 'positionZ', a.position_z,
  'sortOrder', a.sort_order, 'enabled', a.enabled
), CURRENT_TIMESTAMP
FROM acupoint_knowledge a
WHERE NOT EXISTS (
  SELECT 1 FROM copper_acupoint_revision r
  WHERE r.acupoint_code = a.code AND r.version_no = 1
);

-- The body-map learning pool is the same 100 coordinate-ready points used by the copper man.
UPDATE acupoint_knowledge
SET child_traditional_use = CONCAT(
      '传统认识中，“', name, '”常与',
      CASE
        WHEN meridian_code = 'LU' THEN '呼吸、咽喉和胸部舒适'
        WHEN meridian_code = 'LI' AND body_area = '头面与颈部' THEN '口鼻、面部和咽喉舒适'
        WHEN meridian_code = 'LI' THEN '手臂活动以及口鼻、咽喉舒适'
        WHEN meridian_code = 'ST' AND body_area = '头面与颈部' THEN '口鼻、面部和头部舒适'
        WHEN meridian_code = 'ST' AND body_area = '胸部' THEN '胸部舒适和饮食消化'
        WHEN meridian_code = 'ST' AND body_area = '腹部' THEN '饮食、消化和腹部舒适'
        WHEN meridian_code = 'ST' THEN '腿脚活动、饮食和腹部舒适'
        WHEN meridian_code = 'PC' THEN '手腕活动、胸部舒适和情绪安定'
        WHEN meridian_code = 'CV' AND body_area = '头面与颈部' THEN '咽喉、口部和声音舒适'
        WHEN meridian_code = 'CV' AND body_area = '胸部' THEN '呼吸、胸部舒适和情绪安定'
        WHEN meridian_code = 'CV' THEN '饮食、腹部舒适和身体活力'
        ELSE '身体舒适与经络文化'
      END,
      '等身体话题相关。这里只了解传统文化，不用它判断或处理身体不舒服。'
    ),
    traditional_use_source_name = 'GB/T 12346-2021《经穴名称与定位》；《经络腧穴学》课程资料（儿童化改写）',
    traditional_use_source_link = 'https://www.muhn.edu.cn/zyxy/info/1027/7015.htm'
WHERE enabled = 1
  AND position_x IS NOT NULL AND position_y IS NOT NULL AND position_z IS NOT NULL;

UPDATE copper_acupoint_revision r
JOIN acupoint_knowledge a ON a.code = r.acupoint_code
SET r.payload_json = JSON_SET(
      r.payload_json,
      '$.childTraditionalUse', a.child_traditional_use,
      '$.traditionalUseSourceName', a.traditional_use_source_name,
      '$.traditionalUseSourceLink', a.traditional_use_source_link
    )
WHERE a.child_traditional_use IS NOT NULL;

SELECT
  a.code,
  CASE a.body_area
    WHEN '头面与颈部' THEN 'head'
    WHEN '胸部' THEN 'chest'
    WHEN '腹部' THEN 'belly'
    WHEN '肩臂部' THEN 'shoulder'
    WHEN '前臂与肘部' THEN 'forearm'
    WHEN '手腕部' THEN 'wrist'
    WHEN '髋腿部' THEN 'leg'
    WHEN '踝足部' THEN 'ankle'
  END,
  CASE WHEN a.body_area IN ('肩臂部', '前臂与肘部', '髋腿部') THEN 'back' ELSE 'front' END,
  CONCAT(
    '先看',
    CASE WHEN a.body_area IN ('肩臂部', '前臂与肘部', '髋腿部') THEN '右边的背面人物' ELSE '左边的正面人物' END,
    '，再点击“', a.body_area, '”圆圈。沿着圆圈箭头看过去，把“', a.name, '星”送回这个身体区域。'
  ),
  CONCAT('“', a.name, '”在身体地图中属于', a.body_area, '。这里只判断身体大区域，不需要在自己或同学身上寻找穴位。'),
  a.sort_order,
  a.enabled
FROM acupoint_knowledge a
WHERE a.body_area IN ('头面与颈部', '胸部', '腹部', '肩臂部', '前臂与肘部', '手腕部', '髋腿部', '踝足部')
ON DUPLICATE KEY UPDATE
  region_code = VALUES(region_code),
  body_view = VALUES(body_view),
  placement_hint = VALUES(placement_hint),
  child_map_description = VALUES(child_map_description),
  sort_order = VALUES(sort_order),
  enabled = VALUES(enabled);
